SP=[['拉丁语 spirare','吹气、呼吸；更远词源未定']]
SPIRIT=SP+[['拉丁语 spiritus → 古法语 espirit／英法语 spirit','呼吸、生命气息 → 精神、灵魂'],['中古英语 spirit → 英语 spirit','精神、活力；又展开不同专门义']]
SPIRITUAL=SP+[['拉丁语 spiritus → spiritualis；法语 spirituel','精神、灵魂 → 与精神或宗教有关的'],['英语 spiritual','精神的、灵性的；名词又可指灵歌']]
INS=SP+[['拉丁语 in- + spirare → inspirare','吹入、赋予气息 → 激发'],['古法语 inspirer → 中古英语 inspiren → inspire','激发心灵、给人力量']]
INSP=SP+[['拉丁语 inspirare → 晚期拉丁语 inspiratio','吹入、激发 → 启示、感发'],['古法语 inspiracion → 英语 inspiration','启示、灵感；另保留吸气义']]
ASP=SP+[['拉丁语 ad- + spirare → aspirare','向着吹气；追求、希望达到'],['古法语 aspirer → 中古英语 aspiren → aspire','渴望达到、立志']]
EXP=SP+[['拉丁语 ex- + spirare → exspirare / expirare','呼出；呼出最后一口气 → 死去、终止'],['古法语 expirer → 英语 expire','结束、失效；另有呼气与死去义']]
CON=SP+[['拉丁语 con- + spirare → conspirare','共同呼吸 → 一致、联合、共谋']]
PERSP=SP+[['拉丁语 per- + spirare → perspirare','透过而呼出、持续吹气'],['法语 perspiration → 英语 perspiration','经皮肤逸出的湿气 → 汗、出汗']]
RESP=SP+[['拉丁语 re- + spirare → respirare；名词 respiratio','再呼吸、恢复呼吸；呼吸这一过程']]
TRANS=SP+[['中世纪拉丁语 transpirare','trans- 穿过 + spirare 呼吸 → 经表面逸出气体或水汽']]
W=[
E('spirit','/ˈspɪrɪt/','精神；灵魂；活力；态度；本意；烈酒〔常用复数〕','身体还在呼吸，便有生命；这股看不见的生命感，后来也用来说人的劲头和一件事的内在精神。','拉丁 spiritus 从 spirare“呼吸”形成，经法语等进入英语。烈酒义经炼金术中的挥发物、蒸馏物发展；不是因为喝酒会出现鬼魂。',SPIRIT,'team spirit 是团队精神；in good spirits 是心情好；the spirit of the rule 是规则本意。a spirit 还可指故事中的幽灵，spirits 常指烈酒。动词 spirit away 则表示悄悄迅速带走。','team spirit；in high spirits；the spirit of the law；spirit away。','soul 多谈灵魂或一个人的内在本质；spirit 还覆盖劲头、态度、原则等。不同场景不能统译成灵魂。',('The volunteers showed remarkable team spirit.','志愿者表现出了很强的团队精神。'),('The decision followed the spirit of the agreement.','这个决定遵循了协议的本意。'),('The shop sells wine and spirits.','这家店出售葡萄酒和烈酒。'),sources=['https://www.etymonline.com/word/spirit','https://www.oxfordlearnersdictionaries.com/definition/english/spirit_1']),
E('spiritual','/ˈspɪrɪtʃuəl/','精神的；灵性的；宗教的；灵歌','关心一个人心里的意义、信仰和内在体验，而不只是身体或物质生活。','借入法语 spirituel 或拉丁 spiritualis，远接 spiritus。现代可看成 spirit 与 -ual 的关系，但形容词有自己的借入史；名词灵歌由宗教歌曲用法发展。',SPIRITUAL,'spiritual needs 可以是信仰和意义上的需要，不一定限定某个宗教。名词 a spiritual 常指源自美国南方被奴役非洲裔群体传统的宗教民歌，不能随便译成一首“精神歌曲”。','spiritual life；spiritual beliefs；sing a spiritual。','spiritual 说精神或灵性；spirited 说有活力、有劲头，两者不可互换。',('Walking in the mountains became a spiritual experience for her.','在山中行走对她成了一种触及内心的体验。'),('The choir performed several African American spirituals.','合唱团演唱了几首非洲裔美国灵歌。'),sources=['https://www.etymonline.com/word/spiritual','https://www.oxfordlearnersdictionaries.com/definition/english/spiritual_1','https://www.loc.gov/collections/songs-of-america/articles-and-essays/musical-styles/ritual-and-worship/spirituals/']),
E('spiritually','/ˈspɪrɪtʃuəli/','在精神或灵性上；从信仰层面','同一件事，问的不是它让身体怎样，而是它怎样影响内心的意义感与信仰。','spiritual + -ly；描述感受、成长或联系发生在哪个层面。',SPIRITUAL+[['英语 spiritual + -ly → spiritually','精神、灵性的 → 在这个层面上']],'feel spiritually fulfilled 是觉得内心的精神需要得到了满足；spiritually connected 是觉得有深层的精神联系。它不是学习成绩或智力水平的评价。','spiritually fulfilling；grow spiritually；spiritually connected。','mentally 常说心理、认知；spiritually 更常说意义、信仰、灵性，范围有别。',('She found the retreat spiritually refreshing.','她觉得这次静修让自己在精神上焕然一新。'),('The community helped him grow spiritually.','这个社群帮助他在信仰与内在生活上成长。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/spiritually','https://en.wiktionary.org/wiki/spiritually#English']),
E('spirituality','/ˌspɪrɪtʃuˈæləti/','灵性；精神生活；对超越物质意义的追求','把对人生意义、信仰和内在联系的关注，作为一个人的生活层面来谈。','经法语 spiritualite 或晚期拉丁 spiritualitas 借入，接 spiritualis。早期还涉及教会事务与非物质性，现代常说个人的精神生活。',SP+[['拉丁语 spiritus → spiritualis → spiritualitas；法语 spiritualite','精神的性质；亦有教会事务义'],['英语 spirituality','灵性、精神生活与相关追求']],'不同人所说的 spirituality 不完全相同：有人联系宗教仪式，有人强调沉思、自然或人生意义。理解文章时，要看作者怎样界定，不能认定它必然包含某种超自然事实。','personal spirituality；explore spirituality；religion and spirituality。','religion 通常还包括制度、教义、群体和仪式；spirituality 更常指个人内在取向，二者可重叠。',('The essay explores the place of spirituality in everyday life.','随笔探讨了精神生活在日常生活中的位置。'),('Her understanding of spirituality changed over time.','她对灵性的理解随着时间改变了。'),sources=['https://www.etymonline.com/word/spirituality','https://www.oxfordlearnersdictionaries.com/definition/english/spirituality']),
E('spirited','/ˈspɪrɪtɪd/','有活力的；热烈的；有胆气的','身上像有一股劲，做事、发言或反抗都很有生气。','spirit + -ed，表示具有活力、胆气的性质；也与 spirit“鼓舞”的动词分词联系。',SPIRIT+[['英语 spirit + -ed → spirited','精神、活力 → 富有劲头的']],'a spirited debate 是热烈的辩论；a spirited defence 是有力的辩护。它不一定表示声音大，也可以说一个人的积极勇敢。','a spirited performance；a spirited debate；a spirited defence。','spiritual 是精神、宗教方面；spirited 是有活力。热烈的讨论未必讨论宗教。',('The students gave a spirited performance.','学生们演出得生气勃勃。'),('She made a spirited defence of the local library.','她有力地为保留当地的图书馆辩护。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/spirited','https://www.etymonline.com/word/spirited']),
E('dispirited','/dɪˈspɪrɪtɪd/','沮丧的；灰心的','原来那股想继续干下去的劲，好像被抽走了。','dispirit 由 dis- 加 spirit 构成，表示使失去精神；dispirited 是过去分词形成的状态形容词。',SPIRIT+[['英语 dis- + spirit → dispirit → dispirited','使失去劲头 → 灰心的']],'常形容经历失败或受挫后心气低落。它说明当下感受，不等于一个人从此没有能力，也不是医学诊断。','feel dispirited；a dispirited team；leave someone dispirited。','disappointed 是结果不如期待；dispirited 更突出失去干劲，二者常同时出现。',('The team felt dispirited after another cancelled match.','又一场比赛取消后，队员们感到很泄气。'),('A few kind words lifted her dispirited mood.','几句友善的话让她沮丧的心情好转了。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/dispirited','https://www.etymonline.com/word/dispirit']),
E('inspire','英 /ɪnˈspaɪə/；美 /ɪnˈspaɪər/','激励；启发；激起；成为创作来源','像给心里注入一口新气，让人想行动、冒出点子，或产生某种强烈感受。','拉丁 in- + spirare 形成 inspirare“吹入、激发”，经法语进入英语。神意感发是早期重要用法，后来扩展到日常鼓舞与创作。',INS,'inspire someone to do something 是激励某人行动；inspire confidence 是让人有信心；a story inspired a film 是故事成为电影的创作来源。来源相似不等于逐字改编。','inspire someone to；inspire confidence；be inspired by。','encourage 侧重给支持、打气；inspire 常有触动内心、点燃想法的力量。它不只表示灵光一闪。',('Her teacher inspired her to study astronomy.','她的老师激励她去学习天文学。'),('The calm explanation inspired confidence in the team.','冷静清楚的解释让团队产生了信心。'),sources=['https://www.etymonline.com/word/inspire','https://www.oxfordlearnersdictionaries.com/definition/english/inspire']),
E('inspiration','/ˌɪnspəˈreɪʃən/','灵感；启发来源；鼓舞人的人或事；吸气〔生理〕','一个画面、一句话或一个人，让思路突然有了方向，或让你重新愿意向前走。','经法语 inspiracion 接晚期拉丁 inspiratio，来自 inspirare。名词的借入路线独立，不能只画成现代英语 inspire 加 -ation。',INSP,'find inspiration in nature 是从自然获得灵感；an inspiration to others 是能鼓舞别人的榜样。生理学中 inspiration 则是吸气，与 expiration 呼气相对。','a source of inspiration；draw inspiration from；an inspiration to。','idea 是一个想法；inspiration 还包括激发它的过程、力量或来源。医学段落里的吸气义要另看。',('The pattern took its inspiration from falling leaves.','这个图案的灵感来自落叶。'),('Her determination was an inspiration to the younger players.','她的决心鼓舞了年轻队员。'),('The chart labels inspiration and expiration separately.','图表分别标注了吸气和呼气。'),sources=['https://www.etymonline.com/word/inspiration','https://www.oxfordlearnersdictionaries.com/definition/english/inspiration']),
E('inspiring','英 /ɪnˈspaɪərɪŋ/；美 /ɪnˈspaɪrɪŋ/','鼓舞人心的；启发人的','看完、听完之后，别人心里多了一股力量或一个新方向。','inspire 去末尾 e 加 -ing；分词形容词强调产生鼓舞作用。',INS+[['英语 inspire → inspiring','激励 → 能使人受鼓舞的']],'an inspiring speech 是鼓舞人的演讲；an inspiring teacher 是能点燃学生兴趣的人。重点在它对别人的作用。','an inspiring example；an inspiring teacher；find something inspiring。','inspired 说受到启发或富于巧思；inspiring 说使别人受到启发。',('The documentary tells an inspiring story of cooperation.','纪录片讲述了一个鼓舞人心的合作故事。'),('I found her practical optimism inspiring.','她务实而乐观的态度让我很受鼓舞。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/inspiring','https://en.wiktionary.org/wiki/inspiring#English']),
E('inspired','英 /ɪnˈspaɪəd/；美 /ɪnˈspaɪərd/','受到启发的；富于巧思的；受……影响而创作的','想法已经被点亮，或者成品里能看出某个来源留下的痕迹。','inspire + -ed；由被激发的状态，扩展为仿佛灵感迸发而做出的巧妙选择。',INS+[['英语 inspire → inspired','被激发 → 有灵感的、富于巧思的']],'feel inspired 是觉得有了灵感；an inspired choice 是极为巧妙的选择；inspired by a true story 表示受真实故事启发，未必每一幕都是真事。','feel inspired；an inspired choice；inspired by。','inspired 关注被触动的人或巧妙成果；inspiring 关注能触动别人的东西。',('I left the exhibition feeling inspired.','离开展览时，我觉得灵感充沛。'),('Casting her in that role was an inspired choice.','选她来演那个角色是个绝妙的决定。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/inspired','https://en.wiktionary.org/wiki/inspired#English']),
E('inspirational','/ˌɪnspəˈreɪʃənəl/','有激励作用的；旨在鼓舞人的','不仅陈述事实，还希望听者相信自己能做点什么。','inspiration + -al，名词转成性质形容词。',INSP+[['英语 inspiration + -al → inspirational','鼓舞、启发 → 有此作用的']],'inspirational writing 或 speeches 常以鼓励读者、观众为目的。它可以真让人振奋，也可能只是作品类型的名称，效果仍由具体内容决定。','an inspirational speaker；an inspirational message。','inspiring 常直接评价带来的感受；inspirational 也常说作品或讲话的鼓舞性质与用途。',('The coach ended with an inspirational message.','教练最后说了一段鼓舞人心的话。'),('The library displayed inspirational biographies for young readers.','图书馆为年轻读者展示了一批励志传记。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/inspirational','https://en.wiktionary.org/wiki/inspirational#English']),
E('aspire','英 /əˈspaɪə/；美 /əˈspaɪər/','渴望达到；立志','眼光投向一个还没达到的位置，并想努力走到那里。','来自法语 aspirer，接拉丁 ad- + spirare 构成的 aspirare。拉丁词已有向往、追求义；“朝目标喘着气”可作联想，但不是确定的造词现场。',ASP,'aspire to become a writer 是立志成为作家；aspire to excellence 是追求卓越。to 后可以是动词，也可以接名词，注意两种句式。','aspire to do；aspire to something；aspire to leadership。','want 是一般想要；aspire 常说值得长期追求的目标，语气较正式。',('She aspires to become an architect.','她立志成为建筑师。'),('The team aspires to the highest standards of service.','团队致力于达到最高的服务标准。'),sources=['https://www.etymonline.com/word/aspire','https://www.oxfordlearnersdictionaries.com/definition/english/aspire']),
E('aspiration','/ˌæspəˈreɪʃən/','志向；愿望；送气〔语音〕；抽吸、误吸〔医学〕','日常是向往更高目标；专业语境则回到气流、吸入和抽出的动作。','接拉丁 aspiratio、aspirare 及相关借入路线。英语早期已有呼气、语音用义，志向义随后发展；不应把专业名词都画成后来英语 aspirate 动词的产物。',SP+[['拉丁语 aspirare → aspiratio；英语早期 aspiration','吹气 → 呼吸、语音送气等义'],['英语 aspiration 的多条发展','志向；语音送气；医学抽吸或误吸']],'career aspirations 是职业志向。语音学 aspiration 指某些辅音释放后的一股气；医学里可指抽取液体或组织，也可指食物、液体误入气道。后两种需要上下文分辨。','career aspirations；aspirations for the future；needle aspiration。','aspiration 的志向义不等于一般 appetite“胃口”；医学抽吸是操作，误吸是物质进入错误通道，不能互译。',('Her aspirations changed as she gained more experience.','随着经验增加，她的志向也发生了变化。'),('English “pin” usually begins with an audible burst of aspiration.','英语 pin 开头通常带有可听出的送气。'),('The clinician explained that aspiration here meant drawing out a fluid sample.','医生解释说，这里的 aspiration 指抽取液体样本。'),sources=['https://www.etymonline.com/word/aspiration','https://www.oxfordlearnersdictionaries.com/definition/english/aspiration','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/aspiration']),
E('aspirant','英 /əˈspaɪərənt/；美 /ˈæspərənt/','有志者；追求某职位或目标的人','还没得到那个位置，但正朝它努力争取的人。','借自法语 aspirant，名词化的分词；远接拉丁 aspirans、aspirare。现代可用 aspire + -ant 帮记，但并非只在英语内加后缀。',SP+[['拉丁语 aspirare、aspirans → 法语 aspirant','追求 → 追求者'],['英语 aspirant','有志者、职位争取者']],'an aspirant to the leadership 是想争取领导职位的人；也可放在名词前作形容词，如 aspirant writers。较正式，常用于职业、职位或成就目标。','an aspirant to；an aspirant writer；political aspirants。','applicant 是已提出申请的人；aspirant 强调志向，不一定已经正式申请。',('The programme supports young aspirants to a career in science.','这个项目支持有志从事科学工作的年轻人。'),('Several aspirants to the leadership attended the debate.','几位争取领导职位的人参加了辩论。'),sources=['https://www.etymonline.com/word/aspirant','https://www.collinsdictionary.com/dictionary/english/aspirant']),
E('aspirational','/ˌæspəˈreɪʃənəl/','抱有进取愿望的；描绘理想生活的','把目光放到“我想成为的样子”，或把那种生活展示给人看。','aspiration + -al，围绕志向和向往形成形容词。',SP+[['拉丁语 aspirare、aspiratio → 英语 aspiration','追求、志向'],['英语 aspiration + -al → aspirational','与理想目标或生活向往有关的']],'an aspirational target 是有追求性的目标，未必是已经承诺一定实现的指标；aspirational advertising 常展示受众想拥有的生活、身份或成就。','aspirational goals；aspirational advertising；an aspirational lifestyle。','ambitious 强调目标高；aspirational 还可强调令人向往的形象，不保证实际可达。',('The plan sets aspirational goals for the next decade.','计划为未来十年设定了进取性的目标。'),('The campaign uses aspirational images of life by the sea.','宣传活动使用了令人向往的海滨生活画面。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/aspirational','https://en.wiktionary.org/wiki/aspirational#English']),
E('aspirate','动词 /ˈæspəreɪt/；名词、形容词 /ˈæspərət/','送气发音；抽吸；误吸；送气音或抽出物','可以是气从口中送出，也可以是借吸力把物质带入或抽出；专业场景决定方向。','与拉丁 aspiratus“吹气的”、aspirare 相连；动词也有从较早 aspiration 反构的分析。形容词、名词、动词的路线不能简单排成一条现代派生链。',SP+[['拉丁语 aspirare、aspiratus；名词 aspiratio','吹气；被吹出、带气的'],['英语 aspirate 各词性','形容词、名词与动词分别发展；动词可能受 aspiration 反构影响']],'语音课上 aspirate a consonant 是给辅音送气；医学里 aspirate fluid 可说抽取液体，也可说误吸液体。名词 an aspirate 在医疗中可以是抽出的样本。','aspirate a consonant；aspirate fluid；a bone marrow aspirate。','aspire 是立志，aspirate 主要留在语音、医疗等技术场景；不能把 aspire to success 换成 aspirate。',('The teacher demonstrated how to aspirate the initial consonant.','老师示范了怎样在开头的辅音后送气。'),('The laboratory examined the aspirate under a microscope.','实验室用显微镜检查了抽取的样本。'),sources=['https://www.etymonline.com/word/aspirate','https://www.oxfordlearnersdictionaries.com/definition/english/aspirate_1','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/aspiration']),
E('expire','英 /ɪkˈspaɪə/；美 /ɪkˈspaɪər/','到期；失效；呼气〔专业〕；死去〔旧或诙谐〕','给一件事的有效时间画到终点，到那一刻它就不再继续有效。','拉丁 exspirare“呼出”也有呼出最后一口气、结束义，经法语成为 expire。英语早期“死去”义先见，不能说它先在英语里表示呼气才变成死亡。',EXP,'a passport expires 是护照到期；time expires 是时间用尽。技术上的呼气义和旧式死去义仍可见，但现代日常最常谈日期或效力。','a licence expires；expire on a date；expire after a year。','expire 是期限自然走到头；cancel 是人为取消，可能发生在到期之前。',('My passport expires next spring.','我的护照明年春天到期。'),('The link will expire after twenty-four hours.','这个链接将在二十四小时后失效。'),sources=['https://www.etymonline.com/word/expire','https://www.oxfordlearnersdictionaries.com/definition/english/expire']),
E('expiration','英 /ˌekspəˈreɪʃən/；美 /ˌekspəˈreɪʃən/','到期；终止；呼气','把“期限结束”作为一件事来谈；生理学里则是把气呼出去的阶段。','接拉丁 expiratio、exspiratio，由 expirare、exspirare 构成，早期英语有气息、呼出义；终止义后来常用。',SP+[['拉丁语 exspirare → exspiratio / expiratio → 英语 expiration','呼出、气息'],['英语 expiration','期限终止；保留生理呼气义']],'expiration date 在美式英语中很常见；合同的 expiration 是期限届满，不等于当事人突然撕毁合同。肺功能描述里的 expiration 则别译成过期。','an expiration date；upon expiration；during expiration。','expiry 在英式英语中常见，尤其接 date；expiration 也可明确表示呼气。',('The notice gives the expiration date of the offer.','通知列出了优惠的截止日期。'),('The graph shows airflow during expiration.','图表显示了呼气时的气流。'),sources=['https://www.etymonline.com/word/expiration','https://www.oxfordlearnersdictionaries.com/definition/english/expiration']),
E('expiry','英 /ɪkˈspaɪəri/；美 /ɪkˈspaɪəri/','到期；期满；失效日期','用一个名词指出“这东西还能用到什么时候”，或期限结束这件事。','expire 去末尾 e 加 -y；从结束、失效的动作形成名词。',EXP+[['英语 expire + -y → expiry','到期 → 期满及到期时间']],'英式 expiry date 很常见。expiry of a lease 是租约到期；食品、证件、订阅中具体日期代表什么，要看所标的期限类别。','an expiry date；before expiry；expiry of a lease。','expiry 强调期限届满；expiration 在美式日期表达中更常见，两者许多场景可以互换。',('Check the expiry date on your membership card.','查看会员卡上的到期日。'),('The tenant contacted the owner before the lease’s expiry.','租约到期前，租户联系了业主。'),sources=['https://www.etymonline.com/word/expiry','https://www.oxfordlearnersdictionaries.com/definition/english/expiry']),
E('expired','英 /ɪkˈspaɪəd/；美 /ɪkˈspaɪərd/','已到期的；已失效的','那条有效时间线已经走过了终点。','expire + -ed，表示动作已经发生，也可作状态形容词。',EXP+[['英语 expire → expired','到期 → 已经到期的']],'an expired ticket 是过期票；an expired password 是已失效的密码。这个词说的是期限状态，本身不解释当初设定期限的全部原因。','an expired passport；an expired subscription；an expired link。','expiring 是正要或即将到期；expired 是已经到期。unused 只是没用过，未必过期。',('The website rejected the expired password.','网站拒绝了已失效的密码。'),('He accidentally packed an expired travel pass.','他误把一张过期交通通票装进了行李。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/expired','https://en.wiktionary.org/wiki/expired#English']),
E('expiratory','英 /ɪkˈspaɪərətəri/；美 /ɪkˈspaɪrətɔːri/','呼气的；与呼出气体有关的','在一次呼吸中，空气往外走的那一段。','由 expiration 的拉丁式词干配合 -ory 形成，接拉丁 expirare；这里沿用呼气义，不是说证件过期。',SP+[['拉丁语 expirare、expiratio → 英语 expiration','呼气'],['英语 expirat(ion) + -ory → expiratory','与呼出动作相关的']],'expiratory flow 是呼气气流；expiratory phase 是呼气阶段。常在呼吸生理、肺功能或设备说明中出现。','expiratory flow；the expiratory phase；expiratory volume。','inspiratory 是吸气的；expiratory 是呼气的。两个词的方向相反，均不是灵感或日期语境。',('The diagram separates the inspiratory and expiratory phases.','示意图区分了吸气与呼气阶段。'),('The device recorded changes in expiratory flow.','设备记录了呼气气流的变化。'),sources=['https://www.collinsdictionary.com/dictionary/english/expiratory','https://www.merriam-webster.com/dictionary/expiratory']),
E('respiration','/ˌrespəˈreɪʃən/','呼吸；呼吸作用','在身体层面是吸入、呼出与气体交换；在细胞层面是从物质中获取可用能量的一套过程。','借自拉丁 respiratio，来自 respirare“再次呼吸、恢复呼吸”；英语名词有直接借入史。',RESP+[['拉丁语 respiratio → 中古英语 respiracioun → respiration','呼吸过程；后扩展为细胞代谢术语']],'观察胸部起伏是在看 breathing，临床也称 respiration。cellular respiration 则是细胞的能量代谢；不能想成细胞有一对小肺，也不能笼统规定所有形式都使用氧气。','the rate of respiration；cellular respiration；aerobic respiration。','respiration 的范围随领域变化；ventilation 强调空气进出，cellular respiration 强调细胞里的化学过程。',('The nurse recorded the patient’s rate of respiration.','护士记录了患者的呼吸频率。'),('The lesson explains how cellular respiration supplies usable energy.','这节课解释了细胞呼吸如何提供可用能量。'),sources=['https://www.etymonline.com/word/respiration','https://www.oxfordlearnersdictionaries.com/definition/english/respiration','https://openstax.org/books/microbiology/pages/8-3-cellular-respiration']),
E('respiratory','英 /rəˈspɪrətri/、/ˈrespərətri/；美 /ˈrespərətɔːri/','呼吸的；呼吸系统的','把鼻、气道、肺以及吸入呼出的功能放在同一主题下。','借近代拉丁 respiratorius 或法语 respiratoire，接 respirare 的呼吸词干；现代可与 respiration 对照。',SP+[['拉丁语 respirare → 近代拉丁语 respiratorius／法语 respiratoire','呼吸 → 与呼吸相关的'],['英语 respiratory','呼吸的、呼吸系统的']],'respiratory system 是呼吸系统；respiratory symptoms 是与呼吸系统有关的症状。这个形容词只标出领域，不说明某一种病因。','the respiratory system；respiratory function；respiratory symptoms。','respiratory 不是 circulatory“循环的”；前者关注呼吸，后者关注血液等循环。',('The model shows the main parts of the respiratory system.','模型展示了呼吸系统的主要部分。'),('The study measured changes in respiratory function.','研究测量了呼吸功能的变化。'),sources=['https://www.etymonline.com/word/respiratory','https://www.oxfordlearnersdictionaries.com/definition/english/respiratory']),
E('respirator','英 /ˈrespəreɪtə/；美 /ˈrespəreɪtər/','呼吸防护器；呼吸器；辅助呼吸设备〔部分语境〕','有的装置保护吸进来的空气，有的用来辅助呼吸；要先看具体说的是哪一种。','由 respire“呼吸”的相关词干形成器具名，远接拉丁 respirare。早期包括保护口鼻的装置，后有不同技术用法。',SP+[['拉丁语 respirare → 英语 respire','呼吸'],['英语 respirator','由呼吸动作命名帮助或保护呼吸的器具']],'职业防护中的 respirator 可以过滤空气，也可从独立来源供气。医院文字有时用它指辅助呼吸设备，但现代 ventilator 更明确地指机械通气设备；普通口罩也不自动等同于呼吸防护器。','a filtering respirator；a supplied-air respirator；wear a respirator。','respirator 的防护义与 ventilator 的通气义需区分；前者不是所有情况下都主动替人送气。',('The training compared several types of respirator.','培训比较了几种呼吸防护器。'),('Workers wore respirators selected for the task.','工人佩戴了根据该项工作选择的呼吸防护器。'),sources=['https://www.etymonline.com/word/respirator','https://www.oxfordlearnersdictionaries.com/definition/english/respirator','https://www.cdc.gov/niosh/ppe/respirators/']),
E('conspire','英 /kənˈspaɪə/；美 /kənˈspaɪər/','密谋；共谋；共同促成〔也用于事物〕','几个人暗中把方向对齐，一起推某个计划；也可借来说几种坏条件碰巧凑到了一起。','拉丁 con-“共同” + spirare 构成 conspirare，已有一致、联合、共谋义，经法语传入。共同呼吸到合谋的具体转义并无唯一确定故事。',CON+[['古法语 conspirer → 中古英语 conspiren → conspire','联合、共谋；后来也说因素共同促成']],'conspire to deceive 是合谋欺骗；everything conspired against us 是各种条件仿佛一起作对，并不真指天气和交通偷偷开会。','conspire to do；conspire with；conspire against。','cooperate 可公开、正当地合作；conspire 常含秘密或不良目的，事物主语时可以是比喻。',('The characters conspire to hide the missing letter.','这些人物合谋藏起那封失踪的信。'),('Heavy rain and traffic delays conspired to make us late.','大雨和交通延误凑在一起，让我们迟到了。'),sources=['https://www.etymonline.com/word/conspire','https://www.oxfordlearnersdictionaries.com/definition/english/conspire']),
E('conspiracy','/kənˈspɪrəsi/','阴谋；合谋；秘密计划','重点是多人暗中达成的安排，而不只是一个人心里的坏念头。','经英法语 conspiracie 接拉丁 conspiratio，由 conspirare 形成。现代与 conspire 对照，但名词早有独立借入路线。',CON+[['拉丁语 conspiratio → 英法语 conspiracie → 英语 conspiracy','一致、联合 → 秘密合谋']],'a conspiracy to defraud 是合谋诈骗；a conspiracy theory 是用秘密合谋解释事件的说法，是否有证据要另行判断。词的存在既不证明阴谋属实，也不说明所有秘密合作都一样。','a conspiracy to；uncover a conspiracy；a conspiracy theory。','plot 可以是一人的计划，也可说故事情节；conspiracy 通常突出多人参与的秘密合谋。',('The novel centres on a conspiracy to steal a valuable manuscript.','小说围绕一场窃取珍贵手稿的阴谋展开。'),('The investigators found no evidence of a wider conspiracy.','调查人员没有发现更大范围合谋的证据。'),sources=['https://www.etymonline.com/word/conspiracy','https://www.oxfordlearnersdictionaries.com/definition/english/conspiracy']),
E('conspirator','英 /kənˈspɪrətə/；美 /kənˈspɪrətər/','共谋者；阴谋参与者','不是只知道有这个计划，而是参与一起策划或实施的人。','经法语 conspirateur 接拉丁 conspirator、conspiratorem，来自 conspirare；现代可看出人员词尾 -or，但不是直接把英语 conspire 加 -tor。',CON+[['拉丁语 conspirator → 法语 conspirateur → 中古英语 conspiratour','共谋的人'],['英语 conspirator','阴谋或秘密计划的参与者']],'常与 fellow conspirators 连用，说同谋者；故事里也可轻松地把筹备秘密惊喜的人称为 conspirators，语气由上下文决定。','a fellow conspirator；an alleged conspirator。','accomplice 常是参与犯罪的人；conspirator 特别强调共同密谋，法律定义则依制度而定。',('One conspirator revealed the plan to the authorities.','一名共谋者向当局透露了计划。'),('The children exchanged smiles like successful conspirators.','孩子们像密谋得逞的伙伴一样，相互会心一笑。'),sources=['https://www.etymonline.com/word/conspirator','https://www.oxfordlearnersdictionaries.com/definition/english/conspirator']),
E('conspiratorial','英 /kənˌspɪrəˈtɔːriəl/；美 /kənˌspɪrəˈtɔːriəl/','阴谋性的；像在密谋的；神秘会意的','声音压低一点、互相使个眼色，好像只让“我们自己人”知道。','conspirator + -ial，围绕共谋者及其行为形成形容词。',CON+[['拉丁语 conspirator → 法语 conspirateur → 英语 conspirator','共谋者'],['英语 conspirator + -ial → conspiratorial','共谋者式的；像在密谋的']],'a conspiratorial whisper 可以真涉及阴谋，也可只是朋友分享惊喜时的神秘语气。conspiratorial thinking 则常说凡事从秘密合谋角度理解。','a conspiratorial smile；a conspiratorial whisper；a conspiratorial tone。','secretive 是不愿透露；conspiratorial 还带多人共享秘密、互相会意的感觉。',('She gave me a conspiratorial smile and pointed to the hidden cake.','她神秘地朝我会心一笑，指了指藏起来的蛋糕。'),('They lowered their voices to a conspiratorial whisper.','他们压低声音，像在密谋一样小声说话。'),sources=['https://www.etymonline.com/word/conspiratorial','https://www.oxfordlearnersdictionaries.com/definition/english/conspiratorial']),
E('perspire','英 /pəˈspaɪə/；美 /pərˈspaɪər/','出汗','身体表面慢慢冒出汗水，比 sweat 更正式、委婉。','拉丁 perspirare 是透过而呼出；英语 perspire 一方面接相关借词，一方面可从较早 perspiration 反构。不能把 perspiration 一概画成后来英语动词的后代。',[*SP,['拉丁语 perspirare；法语 perspirer、perspiration','经表面逸出气体或湿气'],['英语 perspiration；英语 perspire 的相关借入及反构','湿气逸出 → 出汗']],'人因为热、运动或紧张而 perspire。它通常只是汗从皮肤出来，不表示汗一定很多，更不是某种特殊病名。','perspire heavily；begin to perspire；perspire in the heat。','sweat 是普通直接的说法；perspire 语气更正式，两者并非分别只用于某种性别。',('He began to perspire as the room grew warmer.','房间越来越热，他开始出汗了。'),('She was perspiring after the climb.','爬上去之后，她出汗了。'),sources=['https://www.etymonline.com/word/perspire','https://www.oxfordlearnersdictionaries.com/definition/english/perspire']),
E('perspiration','英 /ˌpɜːspəˈreɪʃən/；美 /ˌpɜːrspəˈreɪʃən/','汗；出汗','汗水从皮肤出来这一过程，以及冒出来的汗本身。','借自法语 perspiration，接 perspirer、拉丁 perspirare。早期指经过皮肤逸出的湿气，后来成为汗的较正式说法；英语记录早于 perspire。',PERSP,'beads of perspiration 是一颗颗汗珠。也可借汗水比喻努力，但不能把“有付出”自动理解成某一句名言的引用。','beads of perspiration；wipe away perspiration；heavy perspiration。','perspiration 与 inspiration 只差开头，却分别是汗与灵感；同样保留呼吸的远源，不同前缀已走出不同义。',('Beads of perspiration formed on his forehead.','他的额头冒出了汗珠。'),('She wiped the perspiration from her face with a towel.','她用毛巾擦掉脸上的汗。'),sources=['https://www.etymonline.com/word/perspiration','https://www.oxfordlearnersdictionaries.com/definition/english/perspiration']),
E('transpire','英 /trænˈspaɪə/；美 /trænˈspaɪər/','被透露；结果发现；发生；蒸腾〔植物〕','秘密像水汽一样透出来，让大家终于知道；植物义则是真正释放水汽。','经法语 transpirer 接 trans- 与 spirare 的构词。先有气液从表面逸出，后比喻消息泄露、事情显露，再有“发生”用法。',TRANS+[['法语 transpirer → 英语 transpire','逸出水汽 → 秘密透出、变得为人所知'],['英语 transpire 的扩展','也用于事情发生；植物蒸腾保留物理义']],'it transpired that... 是后来得知原来……。what transpired 常是发生了什么；这一用法曾被批评，如今词典也收录。生物学语境中 plants transpire 是植物释放水汽。','it transpired that；what transpired；transpire through leaves。','emerge 可说事实浮现；happen 直接说发生。若要表达“后来才知道”，it transpired that 更贴切。',('It later transpired that the address was wrong.','后来才发现，地址是错的。'),('No one could explain exactly what had transpired during the meeting.','没有人能准确说明会议期间发生了什么。'),sources=['https://www.etymonline.com/word/transpire','https://www.oxfordlearnersdictionaries.com/definition/english/transpire']),
E('transpiration','/ˌtrænspəˈreɪʃən/','蒸腾；水汽经生物体表面散失','植物吸来的水，一部分最后从叶片等部位变成水汽进入空气。','英语早期从中世纪拉丁 transpiratio 借入，接 transpirare；名词记录早于英语 transpire，不能由现代外形倒推其先后。',TRANS+[['中世纪拉丁语 transpiratio → 中古英语 transpiracioun','气体或水汽透过表面逸出'],['现代英语 transpiration','尤其指植物的水分蒸腾']],'叶片气孔是水汽散失的重要通道。transpiration 是水循环的一部分，不是植物从空气中直接制造水，也不等于光合作用。','transpiration through leaves；the rate of transpiration；water loss by transpiration。','evaporation 泛指蒸发；transpiration 特指生物体、尤其植物散失水汽。evapotranspiration 合计蒸发与蒸腾。',('The study measured water loss through transpiration.','研究测量了蒸腾造成的水分散失。'),('The diagram shows how transpiration returns water to the atmosphere.','示意图展示了蒸腾如何把水送回大气。'),sources=['https://www.etymonline.com/word/transpiration','https://www.oxfordlearnersdictionaries.com/definition/english/transpiration','https://www.usgs.gov/water-science-school/science/evapotranspiration-and-water-cycle']),
]
COR=[['拉丁语 corpus，属格 corporis','身体；由此提取 corpor- 词干']]
CORP=COR+[['拉丁语 corporare → corporatus → 英语 corporate','使成为一个身体、合为一体 → 团体的、公司的']]
INC=COR+[['晚期拉丁语 in- + corporare → incorporare、incorporatus','使进入一个整体、合为一体'],['中古英语 incorporaten → incorporate','纳入、合并；组成法人组织']]
CORPOREAL=COR+[['拉丁语 corporeus → 英语 corporeal','有身体的 → 有物质形体的']]
INCORPOREAL=COR+[['拉丁语 in- + corporeus → incorporeus','没有物质身体的'],['英语 incorporeal','无形体的、非物质的']]
CORPORAL=COR+[['拉丁语 corporalis','身体的；这一支不是军衔 corporal 的 caput 来源']]
CORPUSCLE=COR+[['拉丁语 corpusculum → 英语 corpuscle','小身体 → 小体、血球、微粒']]
W += [
E('corporate','形容词：英 /ˈkɔːpərət/；美 /ˈkɔːrpərət/','公司的；团体的；共同的','许多人被看成一个整体，这个整体能够共同决策、承担责任，也形成自己的形象。','接拉丁 corporatus“结合成一个身体的”。常见形容词词尾读 /ət/；古旧动词 corporate“合成一体”则读 /eɪt/，不要套到 corporate office 上。',CORP,'corporate culture 是公司文化；corporate identity 是公司整体形象。它常与商业公司有关，但历史上的核心是“组成一个团体”，并不专指规模巨大或逐利的机构。','corporate culture；corporate responsibility；a corporate office。','corporate 说公司或集体；corporeal 说有物质身体。corporate body 可以是法人团体，不能望文生义成肉身。',('The merger brought two different corporate cultures together.','合并让两种不同的公司文化碰到了一起。'),('The report sets out the organization’s corporate responsibilities.','报告列出了该组织作为一个整体的责任。'),sources=['https://www.etymonline.com/word/corporate','https://www.oxfordlearnersdictionaries.com/definition/english/corporate']),
E('corporation','英 /ˌkɔːpəˈreɪʃən/；美 /ˌkɔːrpəˈreɪʃən/','公司；法人团体','把组织在法律上当成一个可以拥有财产、订立合同的“主体”，不只看成若干成员的临时集合。','中古英语 corporation 接英拉丁语及晚期拉丁 corporatio，来自 corporare“使成为一个身体”。名词有独立借入路线。',COR+[['拉丁语 corporare → 晚期拉丁语 corporatio','使成为整体 → 成为一体、团体'],['英拉丁语／中古英语 corporation → 现代英语 corporation','具有组织和法律身份的团体']],'日常常译公司，尤其大公司；不过 corporation 也能是非营利或公共法人。具体法律资格因地区而异，词义重点是组织作为一个整体的身份。','a multinational corporation；a public corporation；a nonprofit corporation。','company 是更宽泛的公司称呼；corporation 强调特定组织、法人身份，不能只靠员工人数判定。',('The corporation opened a new research centre.','这家公司开设了新的研究中心。'),('The museum is managed by a nonprofit corporation.','这家博物馆由一个非营利法人组织管理。'),sources=['https://www.etymonline.com/word/corporation','https://www.oxfordlearnersdictionaries.com/definition/english/corporation']),
E('corps','单数：英 /kɔː/，美 /kɔːr/；复数：英 /kɔːz/，美 /kɔːrz/','军团；兵种部队；有共同工作的群体','许多人像身体的各部分一样协作，组成一个明确的群体。','从法语 corps 借入，源于拉丁 corpus。它与 corpse 同源，但借入时期和用途不同；词尾 ps 在单数不发音。',COR+[['法语 corps，亦用于 corps d’armée','身体 → 组织成一体的部队'],['英语 corps','部队；工作或职业群体']],'the press corps 是记者团；army corps 是军的编制单位。单复数拼写都用 corps，复数读音才加 /z/；不能把 two corps 读成两个尸体。','the diplomatic corps；the press corps；an army corps。','corps 是活人组成的群体；corpse 是遗体，末尾读 /ps/。意义和发音都要分开。',('The press corps waited outside the conference room.','记者团在会议室外等候。'),('Two army corps took part in the exercise.','两个军参加了演习。'),sources=['https://www.etymonline.com/word/corps','https://www.oxfordlearnersdictionaries.com/definition/english/corps']),
E('corpse','英 /kɔːps/；美 /kɔːrps/','尸体；遗体','曾经是活人的身体，如今生命已经停止。','拉丁 corpus 经古法语 cors 进入中古英语。英语早期已经有遗体义；后来按拉丁词形恢复 p，拼写和发音逐步形成 corpse。',COR+[['古法语 cors → 中古英语 cors','身体；英语中早已有遗体义'],['恢复拉丁式 p 等拼写 → corpse','现代主要指尸体、遗体']],'日常通常指人的遗体，语气比 body 直接、生硬。戏剧圈动词 corpse 还可说演员忍不住笑场，是另一专门用法，不应从字面编出确定的起源故事。','a human corpse；identify a corpse；corpse on stage〔戏剧用语〕。','body 可以指活人的身体，也常委婉指遗体；corpse 明确指死后的身体。corps 则是群体。',('The investigators were trying to identify the corpse.','调查人员正试图确认遗体身份。'),('The unexpected noise made one actor corpse on stage.','突如其来的声响让一名演员在台上笑场了。'),sources=['https://www.etymonline.com/word/corpse','https://www.oxfordlearnersdictionaries.com/definition/english/corpse_1','https://www.oxfordlearnersdictionaries.com/definition/english/corpse_2']),
E('corpus','英 /ˈkɔːpəs/；美 /ˈkɔːrpəs/','语料库；文集；作品或资料的总体；体〔解剖〕','把许多材料收在一起，当成一个可以整体研究的“身体”。','直接借入拉丁 corpus“身体、整体”。材料集合义沿用整体的比喻；解剖名称仍保留身体或结构的含义。',COR+[['英语 corpus','物质的体；作品或语言材料组成的整体']],'a corpus of letters 是一批书信材料；语言学 corpus 常指按标准收集、可检索分析的语言资料。它可以含口语转写，不一定全是文学作品，也不天然代表所有语言使用。','a corpus of texts；a spoken corpus；the corpus of an author’s work。','corpus 是可分析的材料集合；dictionary 是解释词语的工具。语料库可以帮助编词典，两者不等同。',('The researchers built a corpus of local newspaper articles.','研究者建立了一个当地报纸文章语料库。'),('The poem belongs to the surviving corpus of her work.','这首诗属于她留存下来的作品。'),sources=['https://www.etymonline.com/word/corpus','https://www.oxfordlearnersdictionaries.com/definition/english/corpus']),
E('corpora','英 /ˈkɔːpərə/；美 /ˈkɔːrpərə/','corpus 的复数：多个语料库、文集或解剖学的体','不是同一个语料库里的几个句子，而是把两个或更多整体分别数出来。','沿用拉丁 corpus 的复数 corpora；-us 变 -ora 是这个拉丁名词的变化，不能套给所有以 -us 结尾的英语词。',COR+[['拉丁语 corpus → 复数 corpora','一个身体、整体 → 多个整体'],['英语 corpora','corpus 的拉丁式复数']],'compare two corpora 是比较两个语料库。语料语境也能见 corpuses，但 corpora 很常用；解剖名称中同样要看它数的是哪一类结构。','large text corpora；compare corpora；spoken and written corpora。','corpora 是复数，不是 corporate 的缩写。a corpus 用单数，these corpora 用复数。',('The study compares three corpora collected in different decades.','研究比较了在不同年代收集的三个语料库。'),('These corpora contain both formal and informal speech.','这些语料库同时包含正式与非正式口语。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/corpus','https://www.merriam-webster.com/dictionary/corpus']),
E('incorporate','英 /ɪnˈkɔːpəreɪt/；美 /ɪnˈkɔːrpəreɪt/','把……纳入；合并；组成公司或法人','原来单独放着的材料，现在成为整体的一部分，像食材混进面团。','晚期拉丁 incorporare、incorporatus 接 in-“进入”与 corporare“成为一体”。常用动词词尾 /eɪt/；少见形容词用法可读 /ət/，另有古旧否定 in- 的异义。',INC,'incorporate feedback into a plan 是把反馈真正放进计划；incorporate a company 是完成相应的公司组织程序。它不只表示并排摆放，常意味着成为结构的一部分。','incorporate something into；incorporate ideas；incorporate a business。','include 只需包含；incorporate 更强调融入整体。企业 incorporate 也不等于必然与另一家公司合并。',('We incorporated the students’ suggestions into the timetable.','我们把学生的建议纳入了时间表。'),('The founders decided to incorporate the business.','创办人决定把业务注册为公司。'),sources=['https://www.etymonline.com/word/incorporate','https://www.oxfordlearnersdictionaries.com/definition/english/incorporate']),
E('incorporation','英 /ɪnˌkɔːpəˈreɪʃən/；美 /ɪnˌkɔːrpəˈreɪʃən/','纳入；合并；公司设立、法人化','把某个部分放进整体，或者让组织取得一个整体的法律身份，这一过程就有了名字。','借入法语 incorporation 或晚期拉丁 incorporatio，来自 incorporare。现代与 incorporate 对应，但历史名词不必先经过英语动词。',COR+[['晚期拉丁语 incorporare → incorporatio；法语 incorporation','使成为一体 → 合入、组成整体'],['英语 incorporation','纳入、合并；法人组织的设立']],'the incorporation of new evidence 是新证据被纳入考量；date of incorporation 是公司设立日期。前者不涉及办公司，后者不是把产品混合起来。','the incorporation of feedback；articles of incorporation；date of incorporation。','incorporation 是过程或设立行为；corporation 是形成的组织。不能把一份成立文件称作一家 incorporation。',('The revision allows the incorporation of new evidence.','这次修订允许纳入新证据。'),('The certificate gives the company’s date of incorporation.','证书载明了公司的设立日期。'),sources=['https://www.etymonline.com/word/incorporation','https://www.oxfordlearnersdictionaries.com/definition/english/incorporation']),
E('incorporated','英 /ɪnˈkɔːpəreɪtɪd/；美 /ɪnˈkɔːrpəreɪtɪd/','已纳入的；已注册为公司的；公司的〔名称后〕','材料已经成为整体的一部分；公司名称后则说明已经取得相应的组织身份。','incorporate + -ed；公司名中的 Incorporated 常缩为 Inc.。这来自“组成法人”的动词义。',INC+[['英语 incorporate → incorporated','纳入、组成公司 → 已完成这种状态']],'The changes were incorporated 表示修改已被纳入。公司后面的 Incorporated 通常是名称的正式组成部分，不是对产品先进、公司有名的评价。','be incorporated into；an incorporated company；Incorporated / Inc.。','integrated 也说融为一体；incorporated 在公司名中有专门组织含义，不能随意替换。',('The corrections have been incorporated into the final version.','更正已纳入最终版本。'),('The letter uses the company’s full name, including “Incorporated.”','信中使用了公司的全名，包括 Incorporated。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/incorporated','https://en.wiktionary.org/wiki/incorporated#English']),
E('unincorporated','英 /ˌʌnɪnˈkɔːpəreɪtɪd/；美 /ˌʌnɪnˈkɔːrpəreɪtɪd/','未设立为法人的；未建制的；未纳入的','某个群体或地区，还没有被纳入所说的那种正式组织结构。','un-“未、非” + incorporated。法律与地理语境分别沿用 incorporated 的不同义。',INC+[['英语 incorporated → unincorporated','已组成相应组织 → 未取得这种组织身份']],'an unincorporated association 是未注册为法人的协会。在美国等地，an unincorporated area 常是不在已建制市镇范围内的地区；并不等于那里无人居住或没有政府管辖。','an unincorporated association；an unincorporated area。','unincorporated 指组织或行政身份；uninhabited 才是无人居住，两者不是一回事。',('The club began as an unincorporated association.','俱乐部最初是一个未注册为法人的协会。'),('They live in an unincorporated area outside the city.','他们住在城外的一片未建制地区。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/unincorporated','https://www.merriam-webster.com/dictionary/unincorporated']),
E('reincorporate','英 /ˌriːɪnˈkɔːpəreɪt/；美 /ˌriːɪnˈkɔːrpəreɪt/','重新纳入；重新合并；重新设立公司','先前分离、遗漏或分开的部分，再次回到整体里面。','re-“再次” + incorporate；同样能用于材料、成员或公司的重新组织。',INC+[['英语 re- + incorporate → reincorporate','纳入 → 再次纳入或重新组建']],'reincorporate an omitted passage 是把删去的段落重新放回去；公司的 reincorporate 则看具体重新设立或改组情形。重点是再一次，并不自动表示恢复全部旧条件。','reincorporate something into；reincorporate a passage；reincorporate a company。','reincorporate 重新纳入整体；reconsider 只是重新考虑，还没有必然改动整体。',('The editor decided to reincorporate the omitted paragraph.','编辑决定把删去的段落重新加回来。'),('The proposal would reincorporate the unit into the larger organization.','提案将把该部门重新纳入较大的组织。'),sources=['https://www.merriam-webster.com/dictionary/reincorporate','https://en.wiktionary.org/wiki/reincorporate#English']),
E('reincorporation','英 /ˌriːɪnˌkɔːpəˈreɪʃən/；美 /ˌriːɪnˌkɔːrpəˈreɪʃən/','重新纳入；重新合并；重新设立公司','讲的是一度离开的部分怎样重新进入整体，而不是单说那个部分本身。','re- + incorporation，也可与 reincorporate 的动作名词对应。',COR+[['晚期拉丁语 incorporatio → 英语 incorporation','纳入、组成整体'],['英语 re- + incorporation → reincorporation','再一次进行纳入或设立']],'the reincorporation of a chapter 是一章内容被重新收入书中。商业文本的 reincorporation 可说重新依法组织公司，含义需由上下文补足。','reincorporation into a group；the reincorporation of material。','incorporation 未必重复；reincorporation 明示再次。它与 reincarnation“转世”也不同。',('Readers welcomed the reincorporation of the missing chapter.','读者欢迎把缺失的章节重新收录进来。'),('The report discusses the unit’s reincorporation into the agency.','报告讨论了该部门重新并入机构的事。'),sources=['https://www.merriam-webster.com/dictionary/reincorporation','https://en.wiktionary.org/wiki/reincorporation#English']),
E('disincorporate','英 /ˌdɪsɪnˈkɔːpəreɪt/；美 /ˌdɪsɪnˈkɔːrpəreɪt/','撤销法人或建制资格；使脱离整体','原先把组织当成一个正式整体的那层身份，被解除或撤回。','dis-“解除、分开” + incorporate；与纳入、组成法人的方向相反。',INC+[['英语 dis- + incorporate → disincorporate','组成整体 → 解除这种整体或法人身份']],'常见于城市撤销建制、公司解除法人地位等正式文本。它说的是组织身份变化，不表示建筑物、居民或财产瞬间消失。少见形容词词尾可读 /ət/。','disincorporate a municipality；vote to disincorporate。','dissolve 更广，可说解散组织；disincorporate 特别突出撤去 incorporation 带来的身份。',('Residents voted on whether to disincorporate the town.','居民就是否撤销该镇建制进行了投票。'),('The document sets out the procedure to disincorporate the body.','文件列出了撤销该团体法人资格的程序。'),sources=['https://www.merriam-webster.com/dictionary/disincorporate','https://en.wiktionary.org/wiki/disincorporate#English']),
E('disincorporation','英 /ˌdɪsɪnˌkɔːpəˈreɪʃən/；美 /ˌdɪsɪnˌkɔːrpəˈreɪʃən/','撤销法人资格；撤销建制；脱离整体','正式的整体身份被取消，这个过程以及结果就叫 disincorporation。','dis- + incorporation；也可与 disincorporate 的动作关系一起理解，不把词尾长度当成历史先后的证据。',COR+[['英语 incorporation → disincorporation','组成法人或整体 → 解除这种状态']],'a plan for disincorporation 讨论如何结束某种公司或市镇建制身份。实际事务还可能需要后续安排，不能只译成“全部没了”。','municipal disincorporation；a disincorporation proposal。','disincorporation 涉及整体资格的解除；relocation 只是搬迁，组织可能原封不动继续存在。',('The proposal for disincorporation was debated at the meeting.','会上讨论了撤销建制的提案。'),('The report examines the administrative effects of disincorporation.','报告考察了撤销建制带来的行政影响。'),sources=['https://en.wiktionary.org/wiki/disincorporation#English','https://www.merriam-webster.com/dictionary/disincorporation']),
E('corporately','英 /ˈkɔːpərətli/；美 /ˈkɔːrpərətli/','作为一个团体地；由公司整体地','做事的主体是整个团体，而不是每位成员各干各的。','corporate + -ly，接公司的、集体的形容词义。',CORP+[['英语 corporate + -ly → corporately','团体的 → 作为整个团体地']],'act corporately 是作为一个整体行动；corporately owned 表示由公司持有。这个副词较正式，通常用在责任、所有权和集体行为的讨论中。','act corporately；corporately owned；corporately responsible。','corporately 是团体、公司层面；corporeally 是肉身、物质身体层面，别漏看中间的 e。',('The trustees agreed to act corporately on the matter.','受托人同意以集体身份处理这件事。'),('The building is corporately owned.','这栋建筑归公司所有。'),sources=['https://www.collinsdictionary.com/dictionary/english/corporately','https://www.merriam-webster.com/dictionary/corporately']),
E('corporative','英 /ˈkɔːpərətɪv/；美 /ˈkɔːrpərətɪv/','团体的、公司的；法团主义的','把社会或组织按一个个行业、职业团体来安排，而不是只看分散的个人。','接拉丁 corporativus，来自 corporare 的词干。英语既有一般团体义，也有政治组织方式的专门义。',COR+[['拉丁语 corporare → corporativus → 英语 corporative','组成团体 → 团体的；后来用于法团制度']],'a corporative system 在政治史里通常涉及行业团体参与代表或管理；普通语境也可近似 corporate。它没有 cooperative 中“合作”的那个构词来源。','a corporative system；corporative representation；a corporative state。','corporative 不等于 cooperative“合作的”；一个按团体组织的制度，也未必各方配合融洽。',('The chapter explains the country’s proposed corporative system.','这一章解释了该国提出的法团制度。'),('Representation was organized on a corporative basis.','代表制度是按团体来组织的。'),sources=['https://www.collinsdictionary.com/dictionary/english/corporative','https://en.wiktionary.org/wiki/corporative#English']),
E('corporatism','英 /ˈkɔːpərɪtɪzəm/；美 /ˈkɔːrpərətɪzəm/','法团主义；按行业团体协调利益的制度；企业支配〔部分用法〕','不只让个人直接发声，而是让行业、雇主、工会等有组织的群体参与协调。','corporate 的词干 + -ism；从团体概念发展出的社会政治术语。不同作者还可能用它批评大企业对公共政策的影响。',CORP+[['英语 corporate 词干 + -ism → corporatism','团体 → 以团体代表、协调为核心的理论或制度']],'读政治史时，先问它指哪种制度：国家统制的行业组织，与协商中的雇主、工会代表，并非完全相同。现代批评语境也可能专说企业利益支配。','state corporatism；corporatism and interest representation。','corporatism 不是 corporation 的复数，也不能一概译成“大公司很多”；它描述一种利益组织或权力安排。',('The course compares several forms of corporatism.','课程比较了法团主义的几种形式。'),('The author uses “corporatism” to criticize the influence of large businesses.','作者用 corporatism 来批评大企业的影响力。'),sources=['https://www.collinsdictionary.com/dictionary/english/corporatism','https://www.merriam-webster.com/dictionary/corporatism']),
E('corporatist','英 /ˈkɔːpərɪtɪst/；美 /ˈkɔːrpərətɪst/','法团主义的；法团主义者','赞成或实行那种通过组织化团体安排社会利益的方式。','corporate 的词干 + -ist，作人名词或性质形容词；与 corporatism 同一术语支线。',CORP+[['英语 corporate 词干 + -ist → corporatist','团体制度 → 支持者或与其有关的']],'a corporatist arrangement 是一种法团式安排；a corporatist 可指该思想的支持者。语境有时带批评意味，但不能只凭词尾判断此人属于哪一党派。','a corporatist model；corporatist institutions；a corporatist thinker。','corporate executive 是公司高管；corporatist 是立场或制度标签。两者不自动互相推出。',('The article describes a corporatist model of wage negotiation.','文章描述了一种法团式工资谈判模式。'),('The historian examines the ideas of several corporatist thinkers.','历史学者考察了几位法团主义思想家的观点。'),sources=['https://www.collinsdictionary.com/dictionary/english/corporatist','https://en.wiktionary.org/wiki/corporatist#English']),
E('corporeal','英 /kɔːˈpɔːriəl/；美 /kɔːrˈpɔːriəl/','有形体的；肉身的；物质的','能作为一个身体存在，而不是只存在于观念、精神或故事中的无形状态。','接拉丁 corporeus“身体的”，英语采用 -al 形容词形式。不要把它当成 corporate“公司的”的拼写变体。',CORPOREAL,'corporeal existence 是肉身存在；a corporeal form 是有物质形体的样子。哲学、宗教和奇幻文学里常见，用来讨论“有没有身体”这道边界。','corporeal existence；a corporeal form；corporeal needs。','physical 更日常、范围也更广；corporeal 常专门突出肉身、物质形体，与 incorporeal 对照。',('In the story, the spirit takes on a corporeal form.','故事中，精灵获得了有形的身体。'),('The essay contrasts spiritual ideals with corporeal needs.','文章把精神理想与身体需求作对照。'),sources=['https://www.etymonline.com/word/corporeal','https://www.oxfordlearnersdictionaries.com/definition/english/corporeal']),
E('corporeally','英 /kɔːˈpɔːriəli/；美 /kɔːrˈpɔːriəli/','以肉身形式；在身体或物质形体上','强调真正以身体出现或发生，而不只是精神上的联系。','corporeal + -ly；副词保留“身体、形体”方向。',CORPOREAL+[['英语 corporeal + -ly → corporeally','有形体的 → 以有形身体的方式']],'较正式、较少见。说 corporeally present 是强调身体在场；奇幻作品里说 appear corporeally，便是以有实体的样子显现。','corporeally present；appear corporeally；exist corporeally。','corporately 是作为团体；corporeally 是以肉身。这个差别不能只靠中文“整体”去记。',('The legend says the spirit appeared corporeally.','传说称精灵以肉身形式显现。'),('The essay asks what it means to be corporeally present.','文章探讨了以肉身在场意味着什么。'),sources=['https://www.merriam-webster.com/dictionary/corporeally','https://www.collinsdictionary.com/dictionary/english/corporeally']),
E('corporeality','英 /kɔːˌpɔːriˈæləti/；美 /kɔːrˌpɔːriˈæləti/','物质形体性；身体性；肉身存在','不是问“这是什么身体”，而是问“作为身体存在”这种性质有什么意义。','corporeal + -ity；将有物质身体的性质名词化。',CORPOREAL+[['英语 corporeal + -ity → corporeality','有形体的 → 肉身存在、身体性']],'在艺术、哲学讨论中，常说舞蹈、触觉、疼痛让人感到自身的 corporeality。它是抽象地谈身体存在，不是 body 的随意长写法。','human corporeality；the corporeality of experience。','corporeality 强调身体存在的性质；corporation 是组织；corpulence 则说身体肥胖，不能串义。',('Dance makes the performer’s corporeality central to the work.','舞蹈把表演者的身体存在放在作品中心。'),('The chapter explores the corporeality of everyday experience.','这一章探讨日常经验中的身体性。'),sources=['https://www.merriam-webster.com/dictionary/corporeality','https://en.wiktionary.org/wiki/corporeality#English']),
E('corporeity','英 /ˌkɔːpəˈriːəti/；美 /ˌkɔːrpəˈriːəti/','有形体性；物质存在〔少见〕','把“有一个真实的物质身体”当成所讨论的性质。','借自法语 corporéité 或中世纪拉丁 corporeitas，远接 corpus。它与 corporeality 近义，但不是后者随意删掉几个字母。',COR+[['中世纪拉丁语 corporeitas；法语 corporéité','身体的性质、物质性'],['英语 corporeity','有形体性、物质存在']],'多见于哲学、旧学术文字。讨论一个存在是否有 corporeity，关注的是它是否具有物质形体，并不在测量体重或身材。','the corporeity of matter；bodily corporeity。','corporeity 与 corporeality 常可近义理解；corpulence 是肥胖，主题不同。',('The philosopher questions the corporeity of the imagined being.','哲学家追问那个设想中的存在是否具有物质形体。'),('The passage treats corporeity as a property of matter.','这段文字把有形体性看成物质的一种性质。'),sources=['https://www.merriam-webster.com/dictionary/corporeity','https://www.collinsdictionary.com/dictionary/english/corporeity']),
E('incorporeal','英 /ˌɪnkɔːˈpɔːriəl/；美 /ˌɪnkɔːrˈpɔːriəl/','无形体的；非物质的；无体的〔法律〕','能够被设想、讨论或拥有，却没有一个可触摸的物质身体。','历史接拉丁 incorporeus“不具身体的”；现代可用 in- + corporeal 帮助理解，但英语并非一定先造 corporeal 再加 in-。',INCORPOREAL,'奇幻故事的 incorporeal spirit 没有实体；法律中的 incorporeal property 常指权利等无体财产。没有物质身体不等于没有作用或没有价值。','an incorporeal being；incorporeal property；an incorporeal form。','invisible 是看不见；incorporeal 是无物质形体。透明或看不见的物体，仍可能有实体。',('The novel describes an incorporeal presence in the room.','小说描写房间里有一种没有形体的存在。'),('The chapter discusses incorporeal rights rather than physical objects.','这一章讨论无体权利，而非实体物件。'),sources=['https://www.etymonline.com/word/incorporeal','https://www.merriam-webster.com/dictionary/incorporeal']),
E('incorporeality','英 /ˌɪnkɔːˌpɔːriˈæləti/；美 /ˌɪnkɔːrˌpɔːriˈæləti/','无形体性；非物质性','把“没有物质身体”这件事，作为一种性质来讨论。','incorporeal + -ity；从形容词形成抽象名词。',INCORPOREAL+[['英语 incorporeal + -ity → incorporeality','无形体的 → 无形体性']],'常见于哲学、神学或文学分析。an argument for incorporeality 是支持某种存在没有物质身体的论证；词本身并不证明这项主张。','the incorporeality of the soul；an argument for incorporeality。','immortality 是不死；incorporeality 是无形体。故事中的存在可以被设定为其中一种或两种。',('The essay examines the traditional idea of the soul’s incorporeality.','文章考察了灵魂没有物质身体的传统观念。'),('Incorporeality is one of the creature’s defining traits in the novel.','无形体是小说中这个生物的主要特征之一。'),sources=['https://www.merriam-webster.com/dictionary/incorporeality','https://en.wiktionary.org/wiki/incorporeality#English']),
E('incorporeity','英 /ˌɪnkɔːpəˈriːəti/；美 /ˌɪnkɔːrpəˈriːəti/','无形体性；非物质性〔少见〕','指没有肉身、没有物质形体的状态，常出现在旧哲学论述里。','接中世纪拉丁 incorporeitas，源于拉丁 incorporeus。借入路线独立，不能只画成较晚英语 corporeity 前面添 in-。',COR+[['拉丁语 incorporeus → 中世纪拉丁语 incorporeitas','无身体的 → 无形体性'],['英语 incorporeity','无形体、非物质的性质']],'与 incorporeality 意义相近，但词形更少见。阅读时用“没有物质身体这一性质”解开即可，不必另外想出一种新的灵魂类型。','the doctrine of incorporeity；incorporeity and immortality。','incorporeity 与 incorporeality 多为同领域近义表达；两者均不同于 invisible“看不见”的视觉描述。',('The old treatise argues for the incorporeity of the soul.','那部旧论著论证灵魂的非物质性。'),('The translator renders “incorporeity” as “absence of a material body.”','译者把 incorporeity 译为“没有物质身体”。'),sources=['https://www.merriam-webster.com/dictionary/incorporeity','https://www.collinsdictionary.com/us/dictionary/english/incorporeity']),
E('extracorporeal','英 /ˌekstrəkɔːˈpɔːriəl/；美 /ˌekstrəkɔːrˈpɔːriəl/','体外的','某个过程离开身体，在外部装置里完成，再与身体连接。','extra-“在……之外” + corporeal“身体的”；是身体空间位置的术语，不是“额外一个身体”。',CORPOREAL+[['英语 extra- + corporeal → extracorporeal','身体的 → 在身体之外的']],'extracorporeal circulation 是体外循环。ECMO 中，血液经过体外人工肺进行气体交换后回到体内；这个词标出过程的位置，本身不说明适用情况。','extracorporeal circulation；extracorporeal membrane oxygenation。','extracorporeal 是体外；incorporeal 是没有物质身体。体外装置当然仍是物质实体。',('The diagram shows an extracorporeal circuit connected to the patient.','示意图显示了一套与患者相连的体外回路。'),('The lecture explains extracorporeal membrane oxygenation.','讲座介绍了体外膜肺氧合。'),sources=['https://www.merriam-webster.com/dictionary/extracorporeal','https://www.nhlbi.nih.gov/health/respiratory-failure/treatment']),
E('corpulent','英 /ˈkɔːpjələnt/；美 /ˈkɔːrpjələnt/','肥胖的；身躯肥大的〔正式、较旧〕','描写一个人的身体厚重、肥大，像把“身体这一团”特别凸显出来。','经法语 corpulent 接拉丁 corpulentus，来自 corpus。这里说体态，不是公司的规模。',COR+[['拉丁语 corpulentus → 法语 corpulent → 英语 corpulent','身体丰厚的 → 肥胖、身躯肥大的']],'常见于旧文学的人物外貌描写，日常直接称呼别人时可能显得无礼。它不是一个具体医学指标，也不能单凭这个形容词推断健康状况。','a corpulent figure；a corpulent gentleman。','corpulent 描写肥胖；stout 也可说结实或粗壮。corporeal 只表示有身体，完全不含胖的意思。',('The novel introduces a corpulent merchant in a bright coat.','小说描写了一位穿鲜艳外套、身躯肥胖的商人。'),('The portrait shows a corpulent figure seated beside a desk.','肖像画中，一位身材肥胖的人坐在书桌旁。'),sources=['https://www.etymonline.com/word/corpulent','https://www.oxfordlearnersdictionaries.com/definition/english/corpulent']),
E('corpulence','英 /ˈkɔːpjələns/；美 /ˈkɔːrpjələns/','肥胖；肥硕的体态〔正式、较旧〕','把身体肥大的状态当作一个特点来写，而不是说一个具体的人。','经法语 corpulence 接拉丁 corpulentia；与 corpulent 同源，名词有自己的借入路线。',COR+[['拉丁语 corpulentus → corpulentia；法语 corpulence','肥胖的 → 肥胖状态'],['英语 corpulence','肥胖、肥硕体态']],'多见于旧式外貌描写或文学分析。使用时常带评价色彩，不宜当作现代医学中精确的测量名称。','a description of corpulence；the character’s corpulence。','corpulence 是体态肥胖；corporeity 是物质形体性。共同有 corpor-，却处在不同讨论层面。',('The narrator describes the mayor’s corpulence in unkind terms.','叙述者用刻薄的措辞描写市长的肥胖体态。'),('The caricature exaggerates the figure’s corpulence.','这幅讽刺画夸大了人物的肥胖。'),sources=['https://www.etymonline.com/word/corpulence','https://www.oxfordlearnersdictionaries.com/definition/english/corpulence']),
E('corpuscle','英 /ˈkɔːpʌsl/；美 /ˈkɔːrpʌsl/','血球；小体；微粒','看起来像一个小小的独立“身体”，于是用身体的指小形式来命名。','借入拉丁 corpusculum“微小的身体”，由 corpus 构成指小词。现代词尾不能简单按字母逐个读出 /kəl/。',CORPUSCLE,'blood corpuscle 常指血细胞；解剖中一些小结构也叫 corpuscle，并非都只是单个细胞。早期物理学里的 corpuscles 是微粒，需按当时理论理解。','a red blood corpuscle；a sensory corpuscle；minute corpuscles。','corpuscle 是小体或微粒；corpus 是体或整体。血球、小型感觉结构和旧物理微粒不能当成同一种东西。',('The old diagram labels a red blood corpuscle.','旧图把一个结构标为红血球。'),('The textbook illustrates a sensory corpuscle beneath the skin.','课本画出了皮下的一种感觉小体。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/corpuscle','https://www.tabers.com/tabersonline/view/Tabers-Dictionary/735901/all/corpuscle']),
E('corpuscular','英 /kɔːˈpʌskjʊlə/；美 /kɔːrˈpʌskjələr/','微粒的；血球的；小体的','把对象按许多小粒、小体来描述，或说与这些小体有关。','corpuscle 的词干配 -ar；更深接拉丁 corpusculum。派生词重音和词中的 /skj/ 都与 corpuscle 不同。',CORPUSCLE+[['英语 corpuscle → corpuscular','小体、微粒 → 与其有关的']],'the corpuscular theory of light 是历史上的光微粒说。血液学的 corpuscular volume 指血细胞体积等指标；要由学科确定“这粒小体”是什么。','the corpuscular theory；mean corpuscular volume。','corpuscular 不保证所说微粒是细胞；旧光学的 corpuscles 也不能未经说明就等同于现代光子概念。',('The lecture compares wave and corpuscular theories of light.','讲座比较了光的波动说和微粒说。'),('The report lists the mean corpuscular volume.','报告列出了平均红细胞体积。'),sources=['https://www.collinsdictionary.com/dictionary/english/corpuscular','https://www.merriam-webster.com/dictionary/corpuscular']),
E('bicorporal','英 /ˌbaɪˈkɔːpərəl/；美 /ˌbaɪˈkɔːrpərəl/','有两个身体的；双体的〔少见〕','图像或描述中的对象有两个身体，像把两具躯体放在同一个形象里。','bi-“二” + corporal“身体的”；在传统星座、象征图像等描述中也使用。',CORPORAL+[['英语 bi- + corporal → bicorporal','二 + 身体的 → 双体的']],'主要用于专业或旧式描述。传统星座术语中可形容以双重形象表现的星座；这里不是说有两家公司。','a bicorporal figure；a bicorporal sign。','bilingual 是双语；bicameral 是两院；bicorporal 才数身体或双重体形。',('The carving presents a bicorporal creature.','雕刻呈现了一个双体生物。'),('The old guide describes the sign as bicorporal.','旧指南把该星座符号描述为双体的。'),sources=['https://www.merriam-webster.com/dictionary/bicorporal','https://en.wiktionary.org/wiki/bicorporal#English']),
E('tricorporal','英 /ˌtraɪˈkɔːpərəl/；美 /ˌtraɪˈkɔːrpərəl/〔按构词标读〕','有三个身体的；三体的〔少见〕','同一个形象以三个身体来呈现，强调数目是三。','tri-“三” + corporal“身体的”；医学等术语中也可能专指数出的三个体状结构。',CORPORAL+[['英语 tri- + corporal → tricorporal','三 + 身体的 → 三体的']],'神话或艺术描述可以说 a tricorporal deity。专业文本要先弄清 corporal 所指的“体”是哪一种结构；不能看到 tri- 就以为在说物理三体问题。','a tricorporal figure；a tricorporal deity。','tricorporal 数身体或体状结构；tricolour 数颜色，tricameral 数室或议院。',('The relief depicts a tricorporal deity.','浮雕描绘了一位三体神祇。'),('The catalogue describes the figure as tricorporal.','目录把这一形象描述为三体的。'),sources=['https://en.wiktionary.org/wiki/tricorporal#English','https://www.merriam-webster.com/dictionary/tricorporal']),
E('concorporate','形容词：英 /kənˈkɔːpərət/，美 /kənˈkɔːrpərət/；动词词尾 /eɪt/〔按构词标读〕','合为一体的；合并、使成为一体〔古旧〕','原来分开的成员或部分，现在被合成一个共同的身体。','借自拉丁 concorporatus，接 concorporare；con- 表共同，corporare 表组成身体。现代可以拆看，但并非只是英语临时拼 con- + corporate。',COR+[['拉丁语 con- + corporare → concorporare、concorporatus','共同 + 组成一体 → 合为一体的'],['英语 concorporate','结合为一体；已联合的']],'古旧宗教、组织或哲学文字中可见，现代通常用 unite、incorporate。名词或主体“联合起来”并不表示每个部分都丧失区别。','concorporate bodies；concorporate into one body。','concorporate 是结合；corporate 是团体的。历史拼写相近不代表日常能随意互换。',('The old charter sought to concorporate the guilds into one body.','旧章程试图把各行会合成一个团体。'),('The treatise describes the members as concorporate.','论著把这些成员描述为合为一体的。'),sources=['https://www.merriam-webster.com/dictionary/concorporate','https://en.wiktionary.org/wiki/concorporate#English']),
E('concorporation','英 /kənˌkɔːpəˈreɪʃən/；美 /kənˌkɔːrpəˈreɪʃən/〔按构词标读〕','合为一体；联合〔古旧〕','重点落在“原来分开的部分成为同一个整体”这件事上。','接拉丁 concorporatio，来自 concorporare“共同成为一个身体”。现代可对应 concorporate，但名词已有拉丁来源。',COR+[['拉丁语 concorporare → concorporatio','合成一体 → 合为一体的过程'],['英语 concorporation','联合、合一']],'在旧式文本中，可说群体、组成部分的合一。它比现代 merger、union 少见得多，阅读时用“合成一个共同整体”便容易抓住意思。','concorporation into one body；the concorporation of groups。','concorporation 强调整体合一；cooperation 只需合作，合作的两方完全可以保持独立。',('The passage calls for the concorporation of the scattered groups.','这段文字主张让分散的群体合为一体。'),('The historian explains the charter’s idea of concorporation.','历史学者解释了章程中合为一体的观念。'),sources=['https://en.wiktionary.org/wiki/concorporation#English']),
E('corporality','英 /ˌkɔːpəˈræləti/；美 /ˌkɔːrpəˈræləti/','身体存在；肉身性〔少见〕','从肉身这一侧看一个存在：它有身体，有物质形态。','借入晚期拉丁 corporalitas，来自 corporalis“身体的”。现代看似 corporal + -ity，但不是公司 corporate 的普通派生词。',CORPORAL+[['晚期拉丁语 corporalitas → 英语 corporality','身体的性质 → 肉身性、身体存在']],'主要见于旧哲学或宗教文字；某些历史文本也有团体、行会义，仍需看上下文。现代讨论身体性时，更常见 corporeality。','human corporality；the corporality of existence。','corporality 与 corporeality 可近义；corporate responsibility 则说团体责任，不是身体性质。',('The essay connects human corporality with hunger and fatigue.','文章把人的肉身性与饥饿、疲劳联系起来。'),('The translator explains the older term “corporality” in a note.','译者在注释中解释了较古旧的术语 corporality。'),sources=['https://www.merriam-webster.com/dictionary/corporality','https://en.wiktionary.org/wiki/corporality#English']),
E('corporature','英 /ˈkɔːpərətʃə/；美 /ˈkɔːrpərətʃər/','身体存在；体形、体质〔废旧〕','描写一个存在实际具有怎样的身体，或强调它是有肉身的。','可辨认 corpor- 的身体词干和 -ature 词尾；可核义项属于身体存在、体形。具体借入中介不宜硬定，更不能误解为现代公司的制度。',[['拉丁语 corpus、corpor- 词干','身体'],['英语 corporature〔具体中介未确定〕','身体存在、体形；现已废旧']],'阅读旧文献时，把它放回肉身、体质的主题即可。现代写作通常直接用 bodily form、physique 或 bodily existence，不必为了显得正式而使用它。','bodily corporature〔旧式表达〕；a description of corporature。','corporature 不是 corporate culture 的缩写；corporation 也是另一种组织词义。',('The old passage uses “corporature” to discuss bodily existence.','旧文用 corporature 来讨论身体的存在。'),('The editor glosses “corporature” as bodily form.','编辑把 corporature 注释为体形。'),sources=['https://en.wiktionary.org/wiki/corporature#English']),
]
MECH=[['古希腊语 mekhane；多里斯方言 makhana','工具、装置，也可指巧妙办法；更远来源有争议']]
MACHINE=MECH+[['拉丁语 machina → 中古法语 machine → 英语 machine','装置、工具 → 机器']]
MECHANIC=MECH+[['希腊语 mekhanikos → 拉丁语 mechanicus；古法语 mecanique','与器械、技艺有关的'],['中古英语 mechanic → 现代英语 mechanic','手艺工人 → 机械修理工；另有规则、机制义']]
MECHANICAL=MECHANIC[:-1]+[['中古英语 mechanic + -al → mechanical','与技艺、机械有关的；后扩展为机械式的']]
MECHANISM=MECH+[['近代拉丁语 mechanismus → 英语 mechanism','装置的结构 → 运行机构、作用机制']]
MECHANIZE=MECHANIC[:-1]+[['英语 mechanic 的机械词干 + -ize → mechanize','使成为机械式 → 使用机器、机械化']]
MACHINATION=MECH+[['拉丁语 machina → machinari → machinatio','装置、巧计 → 设计、谋划 → 计谋'],['古法语 machinacion／拉丁语 machinatio → 英语 machination','计谋、密谋']]
W += [
E('machine','/məˈʃiːn/','机器；机械装置；计算机；组织机器〔比喻〕；用机器加工','零件配合起来，把力、能量或指令变成一项工作。','借自中古法语 machine，接拉丁 machina、多里斯希腊 makhana。希腊词既可指工具，也可指巧妙办法；英语动词则从机器名词发展。',MACHINE,'washing machine 是洗衣机，a new machine 在工作中也可能指电脑。political machine 比喻严密运作的政治组织；动词 machine a part 是用机床加工零件，不是发明机器。','a washing machine；a virtual machine；machine a metal part。','machine 是具体装置或系统；mechanism 可指其中的机构或背后的运作方式。不是所有机器都只有齿轮。',('The machine sorts envelopes by size.','这台机器按尺寸分拣信封。'),('The workshop machines small parts for bicycles.','车间用机床加工自行车的小零件。'),sources=['https://www.etymonline.com/word/machine','https://www.oxfordlearnersdictionaries.com/definition/english/machine_1','https://www.oxfordlearnersdictionaries.com/definition/english/machine_2']),
E('mechanism','/ˈmekənɪzəm/','机械装置；机构；机制；方法','别只看结果，要打开里面，看看各个环节怎样接力把结果做出来。','借入近代拉丁 mechanismus，远接希腊 mekhane。不是把现代 machine 的声音随意变一变形成的词。',MECHANISM,'a locking mechanism 是锁定机构；a mechanism for resolving disputes 是解决争议的机制；a biological mechanism 是生物过程中各环节怎样起作用。后两者不必有金属零件。','a safety mechanism；the underlying mechanism；a mechanism for doing。','method 可以是你选的做法；mechanism 更常强调一个过程如何运转、通过哪些环节生效。',('The engineer inspected the locking mechanism.','工程师检查了锁定机构。'),('The team proposed a mechanism for resolving disagreements.','团队提出了一套解决分歧的机制。'),sources=['https://www.etymonline.com/word/mechanism','https://www.oxfordlearnersdictionaries.com/definition/english/mechanism']),
E('mechanic','/məˈkænɪk/','机械修理工；技工；规则、玩法机制〔游戏等〕','常见场景是一个人打开机器，找出哪里卡住、磨损，再让它重新正常运转。','经法语等接拉丁 mechanicus、希腊 mekhanikos“与器械、技艺有关的”。英语早有形容词，名词发展出手艺人、修理工；游戏的 mechanic 是规则机制的另一用法。',MECHANIC,'car mechanic 是汽车修理工；a game mechanic 则是推动玩法的一条规则，如消耗能量才能行动。它不是游戏里修车的人，需由语境判断。','a car mechanic；an aircraft mechanic；a game mechanic。','mechanic 常负责检修维护；machinist 常擅长操作机床加工。岗位可交叉，但词的重点不同。',('The mechanic found a loose connection in the engine.','修理工发现发动机里有一处连接松动。'),('The game introduces a mechanic that rewards cooperation.','游戏引入了一种鼓励合作的玩法机制。'),sources=['https://www.etymonline.com/word/mechanic','https://www.oxfordlearnersdictionaries.com/definition/english/mechanic','https://en.wiktionary.org/wiki/mechanic#English']),
E('mechanics','/məˈkænɪks/','力学；运作方式、具体步骤；机械技术；修理工们〔复数〕','一方面问物体受力后怎样运动；另一方面把一件事的运转步骤拆开来看。','学科名称以晚期拉丁 mechanica、希腊 mekhanike 等为背景，并采用学科词尾 -ics。另一个同形用法只是 mechanic“修理工”的复数。',MECH+[['希腊语 mekhanike／mekhanika → 晚期拉丁语 mechanica','器械技艺及其理论'],['英语 mechanics〔学科 -ics〕','力学；扩展为事情的运作细节']],'Mechanics is a branch of physics 中按学科单数用 is。the mechanics of voting 是投票的具体流程，常按复数处理。two mechanics 则是在数两位修理工。','classical mechanics；the mechanics of a process；writing mechanics。','mechanics 是学科或运作细节；mechanism 是一个机构或因果过程。写作里的 mechanics 还可说拼写、标点等规范。',('Mechanics is part of the first year of the course.','力学是这门课程第一年的内容之一。'),('The guide explains the mechanics of submitting an application.','指南解释了提交申请的具体流程。'),('Two mechanics checked the aircraft before departure.','两名机务人员在起飞前检查了飞机。'),sources=['https://www.etymonline.com/word/mechanics','https://www.oxfordlearnersdictionaries.com/definition/english/mechanics']),
E('mechanical','/məˈkænɪkəl/','机械的；机械原理的；呆板、机械式的','字面上说机器怎样动；比喻时说人像照程序运转，动作有了，心思没有跟上。','中古英语 mechanic + -al；接的是与器械、手艺相关的形容词支线，不是先有现代汽车修理工再变形。',MECHANICAL,'mechanical failure 是机械故障；mechanical engineering 是机械工程；a mechanical smile 则是勉强、没什么感情的笑。少数名词用法见于旧戏剧、印刷或行业语境。','mechanical engineering；a mechanical problem；a mechanical response。','mechanical 常说机器部件和物理运动；mechanistic 常说用机制解释事物的观点。后者不一定在批评呆板。',('The delay was caused by a mechanical fault.','延误由一处机械故障造成。'),('He gave a mechanical smile and returned to his work.','他机械地笑了一下，又回去工作了。'),sources=['https://www.etymonline.com/word/mechanical','https://www.oxfordlearnersdictionaries.com/definition/english/mechanical']),
E('mechanically','/məˈkænɪkli/','用机械方式；在机械性能上；机械地、下意识地','一支说机器在做，一支说人虽然在动，却像没有认真想。','mechanical + -ly，拼写为 mechanically，常用读音不逐个展开全部字母。',MECHANICAL+[['英语 mechanical + -ly → mechanically','机械的 → 以机械方式；不加思索地']],'mechanically sound 是机械状况良好；mechanically operated 是机械驱动或操作；repeat mechanically 是不动脑筋地重复。看它修饰的是设备状态，还是人的行为。','mechanically sound；mechanically operated；repeat mechanically。','automatically 常说自动触发或执行；mechanically 还可说机器状况，或批评动作缺乏思考、感情。',('The old vehicle is still mechanically sound.','这辆旧车的机械状况仍然良好。'),('She nodded mechanically while thinking about something else.','她一边想着别的事，一边机械地点头。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/mechanically','https://en.wiktionary.org/wiki/mechanically#English']),
E('machinery','/məˈʃiːnəri/','机器设备；机械部件；运作体系','把一整套机器或运作部件装进同一个篮子里谈，不一台台数。','machine + 集合词尾 -ery，法语也有 machinerie。由设备整体扩展为制度、组织的运作体系。',MACHINE+[['英语 machine + -ery → machinery','机器 → 机器设备的集合；组织运转系统']],'industrial machinery 是工业设备；the machinery of government 是政府运作体系。通常不可数，说 a piece of machinery，日常不说一台 a machinery。','heavy machinery；agricultural machinery；the machinery of government。','machines 是可以一台台数的复数；machinery 强调整体设备。infrastructure 的范围还可包括道路、网络等。',('The factory replaced its ageing machinery.','工厂更换了老化的机器设备。'),('The article explains how the machinery of government works.','文章解释了政府运作体系怎样运转。'),sources=['https://www.etymonline.com/word/machinery','https://www.oxfordlearnersdictionaries.com/definition/english/machinery']),
E('machinist','/məˈʃiːnɪst/','机床工；机械加工技工；机器操作工','读图纸、操作机床，把一块材料加工成尺寸合适的零件。','现代可辨 machine + -ist；词源资料分别采用英语派生和法语 machiniste 借入分析，均接 machine 这一支，不硬定单一路线。',MECH+[['拉丁语 machina → 法语／英语 machine','机器、装置'],['法语 machiniste／英语 machine + -ist → machinist','制造、操作机器的人 → 机床加工技工']],'现代常指熟练使用车床、铣床等加工设备的人；有些行业也泛指机器操作工，历史上还可指舞台布景机械人员。','a skilled machinist；a CNC machinist；an apprentice machinist。','machinist 常重加工制造；mechanic 常重检修维护。工程师 engineer 则是另一种较宽的专业角色。',('The machinist checked the dimensions of the finished part.','机床工检查了成品零件的尺寸。'),('She trained as a machinist before moving into design.','转向设计工作前，她接受过机械加工技工培训。'),sources=['https://www.etymonline.com/word/machinist','https://en.wiktionary.org/wiki/machinist#English','https://www.oxfordlearnersdictionaries.com/definition/english/machinist']),
E('mechanize','/ˈmekənaɪz/','使机械化；用机器完成','原来靠人手或畜力反复做的步骤，改成让机器承担。','mechanic 的机械词干 + -ize；英式也常拼 mechanise。词义由使成机械状态发展为广泛采用机器。',MECHANIZE,'mechanize production 是使生产机械化。操作员仍可能需要全程驾驶、控制或调整机器，因此不必然等于完全自动化。','mechanize agriculture；mechanize production；a fully mechanized process。','mechanize 引入机器；automate 强调过程自动执行、减少即时人工控制。机器化可以只是自动化的一部分。',('The farm began to mechanize its harvesting operations.','农场开始让收割作业机械化。'),('The workshop mechanized a task that had taken hours by hand.','车间把一项手工要做数小时的工作改为机械操作。'),sources=['https://www.etymonline.com/word/mechanize','https://www.oxfordlearnersdictionaries.com/definition/english/mechanize']),
E('mechanization','英 /ˌmekənaɪˈzeɪʃən/；美 /ˌmekənəˈzeɪʃən/','机械化','生产或工作过程逐渐换上机器，这种转变整体叫机械化。','mechanize + -ation；英式也拼 mechanisation。名词说的是过程或程度，不是某一台具体机器。',MECHANIZE+[['英语 mechanize + -ation → mechanization','用机器完成 → 机械化过程']],'agricultural mechanization 包括耕作、播种、收割等采用机械。它可能改变工作量、技能需求和生产组织，但这些具体效果要由实际条件决定。','agricultural mechanization；the mechanization of production。','machinery 是设备；mechanization 是采用设备带来的过程变化。买到设备也不代表整条流程已经机械化。',('Mechanization changed the skills needed on the farm.','机械化改变了农场所需的技能。'),('The report traces the mechanization of textile production.','报告追溯了纺织生产机械化的过程。'),sources=['https://www.etymonline.com/word/mechanization','https://www.oxfordlearnersdictionaries.com/definition/english/mechanization']),
E('mechanized','/ˈmekənaɪzd/','机械化的；配备机械车辆的〔军事等〕','机器已成为这项工作或这支队伍运作的重要部分。','mechanize + -ed；英式常拼 mechanised。军事义尤其涉及使用机械车辆和装备。',MECHANIZE+[['英语 mechanize → mechanized','机械化 → 已使用机器的']],'mechanized farming 是机械化耕作；mechanized infantry 通常依靠装甲运输车辆机动作战。这个词说设备与作业方式，不表示每个环节都无人参与。','mechanized agriculture；mechanized equipment；mechanized infantry。','mechanized 强调机械装备；motorized 通常强调机动车辆，具体军事编制含义随语境不同。',('Mechanized harvesting reduced the amount of manual cutting.','机械化收割减少了手工切割的工作量。'),('The museum displays vehicles used by mechanized infantry.','博物馆展出了机械化步兵使用过的车辆。'),sources=['https://www.etymonline.com/word/mechanized','https://www.oxfordlearnersdictionaries.com/definition/english/mechanized']),
E('mechanistic','/ˌmekəˈnɪstɪk/','机制性的；机械论的；机械式的','想把事情拆成几个环节，说明前一步怎样推动后一步。','mechanical 或 mechanism 的 mechan- 词干 + -istic；既有哲学机械论用法，也有一般机制解释的用法。',MECH+[['英语 mechanical／mechanism 的 mechan- + -istic → mechanistic','机制、机械 → 用机制解释的；机械论的']],'a mechanistic explanation 可以是很有价值的因果解释，例如说明分子怎样相互作用。评论人的行为时，mechanistic view 也可能批评把人看得过于简单、像机器。不能一律译成呆板。','a mechanistic explanation；mechanistic evidence；a mechanistic view。','mechanical 常说机械装置或行为呆板；mechanistic 常说解释方式。科学里的机制性证据不等于“只研究齿轮”。',('The experiment provides evidence for a mechanistic explanation.','实验为一种机制性解释提供了证据。'),('The critic rejected a mechanistic view of human creativity.','评论者反对用机械论看待人的创造力。'),sources=['https://www.merriam-webster.com/dictionary/mechanistic','https://www.oxfordlearnersdictionaries.com/definition/english/mechanistic']),
E('mechanistically','/ˌmekəˈnɪstɪkli/','从作用机制上；以机械论方式','不只问两件事是否一起发生，还问中间到底经过哪几步。','mechanistic + -ally；意义随机制解释或机械论观点而变化。',MECH+[['英语 mechanical／mechanism 的词干 → mechanistic','机制性的、机械论的'],['英语 mechanistic → mechanistically','从机制层面地']],'mechanistically distinct pathways 表示两条过程的具体作用环节不同。mechanistically explain a result 是提出环节之间如何连接；只观察到相关并不自动完成这一步。','mechanistically distinct；mechanistically explain；mechanistically plausible。','statistically 说统计关系；mechanistically 说运作机制。统计结果可以提示机制，却不必然证明机制。',('The two processes look similar but are mechanistically distinct.','这两个过程看起来相似，作用机制却不同。'),('The paper tries to explain the effect mechanistically.','论文试图从作用机制上解释这一效应。'),sources=['https://www.merriam-webster.com/dictionary/mechanistic','https://www.collinsdictionary.com/dictionary/english/mechanistically']),
E('biomechanics','英 /ˌbaɪəʊməˈkænɪks/；美 /ˌbaɪoʊməˈkænɪks/','生物力学','把走路、跳跃、组织受拉等生命现象，放进力与运动的框架里研究。','bio-“生命、生物” + mechanics“力学”；是现代组合，不是某个古希腊学科名原样传下来。',MECH+[['希腊、拉丁力学术语 → 英语 mechanics','研究力、运动与变形'],['英语 bio- + mechanics → biomechanics','研究生物系统中的力学']],'可以研究跑者落地时的受力、骨骼承载，也可研究植物、细胞等生物系统。它不限于运动员，更不是“给生物装机器”的同义词。','the biomechanics of walking；sports biomechanics；plant biomechanics。','biomechanics 广泛研究生物系统的力学；mechanobiology 常突出力怎样改变细胞和组织的生物行为，两者相交。',('The team studied the biomechanics of walking on uneven ground.','团队研究了在不平地面行走的生物力学。'),('Plant biomechanics helps explain how stems resist bending.','植物生物力学有助于解释茎秆怎样抵抗弯曲。'),sources=['https://www.merriam-webster.com/dictionary/biomechanics','https://www.collinsdictionary.com/dictionary/english/biomechanics','https://asbweb.org/']),
E('mechanobiology','英 /ˌmekənəʊbaɪˈɒlədʒi/；美 /ˌmekənoʊbaɪˈɑːlədʒi/〔按构词标读〕','力学生物学','细胞不只接收化学信号，也会感受到被拉、被挤、周围有多软硬，并作出反应。','mechano-“力学、机械作用” + biology“生物学”。研究名称把物理作用与生命过程连接起来。',MECH+[['现代构词成分 mechano- + biology → mechanobiology','机械力、力学性质 + 生物学']],'常研究机械力、组织刚度等如何影响细胞行为、发育与疾病相关过程。重点是力与生物活动的相互影响，不是把人体比喻成机器就算完成解释。','cellular mechanobiology；mechanobiology of tissues。','biomechanics 可着重计算力和变形；mechanobiology 常追问这些力怎样引发或改变生物反应，边界并非完全分开。',('The laboratory studies the mechanobiology of cell migration.','实验室研究细胞迁移的力学生物学。'),('The course examines how tissue stiffness matters in mechanobiology.','课程考察组织刚度在力学生物学中的作用。'),sources=['https://cde.nus.edu.sg/bme/research/research-areas/','https://en.wiktionary.org/wiki/mechanobiology#English']),
E('mechatronics','英 /ˌmekəˈtrɒnɪks/；美 /ˌmekəˈtrɑːnɪks/','机电一体化；机械电子工程','机器有能动的部件，也有感知、控制与程序，把它们一起设计，才形成完整系统。','由机械一侧的 mecha- 与 electronics 的后部融合。词典常拆 mechanics + electronics；安川的命名史明确表述为 mechanism + electronics，1969 年提出申请、1972 年注册。',[['mechanism／mechanics 的机械成分 + electronics','机械机构 + 电子控制'],['安川提出的 mechatronics → 通用工程术语','机械、电子、计算与控制的整合设计']],'自动对焦、机器人和生产设备都可以涉及 mechatronics。重点不是把现成电路随便装在机器旁边，而是让机械、电子与控制功能相互配合。','a mechatronics course；mechatronics engineering；a mechatronics system。','mechanics 主要是力学；electronics 研究电子系统；mechatronics 强调二者与控制、计算的整合。',('She studies mechatronics and works on robotic grippers.','她学习机电一体化，并研究机器人夹爪。'),('The project combines sensors, motors and control software through mechatronics.','项目通过机电一体化整合传感器、电机与控制软件。'),sources=['https://www.yaskawa-global.com/milestones/1960s','https://www.yaskawa-global.com/technology/core-technology','https://www.collinsdictionary.com/dictionary/english/mechatronics']),
E('machination','/ˌmæʃɪˈneɪʃən/；亦有 /ˌmækɪˈneɪʃən/ 等读法','阴谋；暗中策划；巧计〔常用复数〕','像把机关一道道排好，让别人不知不觉走到策划者想要的结果。','古法语 machinacion 或拉丁 machinatio 借入；接 machinari“设计、谋划”、machina“装置、计策”。英语名词早于 machinate。',MACHINATION,'political machinations 常指幕后复杂的算计，通常带贬义。它不是 machine“机器”的一般名词形式，也不是普通公开周密的工作计划。','political machinations；secret machinations；the machinations of a rival。','plan 可以中性；machination 常暗示隐蔽、复杂且不光彩。machine 的实体机器义与这里的计策义是同源分支。',('The novel reveals the minister’s secret machinations.','小说揭露了大臣暗中的阴谋。'),('She wanted no part in the rival group’s machinations.','她不愿参与对手团体的幕后算计。'),sources=['https://www.etymonline.com/word/machination','https://www.oxfordlearnersdictionaries.com/definition/english/machination','https://www.collinsdictionary.com/dictionary/english/machination']),
E('machinate','英 /ˈmækɪneɪt/，亦 /ˈmæʃɪneɪt/；美 /ˈmækəneɪt/','密谋；精心策划阴谋〔正式、少见〕','不是公开商量怎么做，而是在暗处安排步骤，把局面导向自己的目的。','词源有从较早 machination 逆构、或直接接拉丁 machinatus 的分析。现代可与 machination 对应，但不能把名词历史一概放到动词后面。',MECH+[['拉丁语 machina → machinari、machinatus','装置、计策 → 设计、谋划'],['英语 machinate：可能直接借入，也可能由 machination 逆构','暗中谋划、策划']],'可及物说 machinate a plot，也可不及物说 machinate against someone。日常更常用 plot、scheme；machinate 带书面、戏剧性的感觉。','machinate against someone；machinate a scheme。','machine 作动词是用机器加工；machinate 是谋划阴谋，动作对象完全不同。',('The rivals continued to machinate against the new leader.','对手们继续暗中算计新领导人。'),('The villain machinates a scheme to seize the estate.','反派策划了一场夺取庄园的阴谋。'),sources=['https://www.etymonline.com/word/machinate','https://www.collinsdictionary.com/dictionary/english/machinate']),
E('machinator','英 /ˈmækɪneɪtə/；美 /ˈmækəneɪtər/〔依所引词典派生读法整理〕','阴谋策划者；密谋者〔少见〕','机关和计策的背后，总有那个负责安排的人。','韦氏接拉丁 machinator，来自 machinatus 的词干与 -or；柯林斯也按 machinate 的派生词说明。不能误拆成机器操作员。',MECH+[['拉丁语 machina → machinari → machinator','计策 → 谋划 → 谋划者'],['英语 machinator','阴谋策划者；现代与 machinate 对应']],'常用于历史、政治或小说评论，带明显的指责意味。它指背后设计计谋的人，不必是最终亲自实施每一步的人。','a political machinator；a cunning machinator。','machinator 是策划阴谋的人；machinist 是机械加工或操作人员。词形接近，职业评价却完全不同。',('The historian portrays him as a ruthless political machinator.','历史学者把他描写成冷酷的政治阴谋家。'),('The final chapter reveals the machinator behind the deception.','最后一章揭示了骗局背后的策划者。'),sources=['https://www.merriam-webster.com/dictionary/machinator','https://www.collinsdictionary.com/dictionary/english/machinate']),
E('mechanophilia','/ˌmekənəˈfɪliə/〔按构词标读〕','对机器的迷恋、喜爱〔少见〕','目光特别容易被机器吸引：它的形状、声音、动作让人着迷。','mechano-“机器” + -philia“喜爱、吸引”。是现代构词，不能把它当成古希腊已经存在的整词。',MECH+[['现代英语 mechano- + -philia → mechanophilia','机器 + 喜爱、吸引 → 机器迷恋']],'有的文本泛指迷恋机器，有的专指对机器的性吸引，必须看作者语境。仅仅喜欢汽车或机械设计，不足以据这个少见词给人作诊断。','mechanophilia in fiction；a discussion of mechanophilia。','technophilia 是对技术的爱好，范围更广；mechanophilia 更聚焦机器，有时还有更窄的特殊含义。',('The essay uses “mechanophilia” to describe a fascination with machines.','文章用 mechanophilia 来描述对机器的迷恋。'),('The critic discusses mechanophilia in the film’s portrayal of technology.','评论者讨论了影片表现技术时呈现的机器迷恋。'),sources=['https://en.wiktionary.org/wiki/mechanophilia#English']),
E('mechanophobia','英 /ˌmekənəˈfəʊbiə/；美 /ˌmekənəˈfoʊbiə/〔按构词标读〕','对机器的恐惧〔少见〕','看到或想到机器时，注意力先落到威胁和害怕上。','mechano-“机器” + -phobia“恐惧”；现代结合词，不是从 mechanic“修理工”变来的。',MECH+[['现代英语 mechano- + -phobia → mechanophobia','机器 + 恐惧 → 对机器的害怕']],'可见于讨论人机关系或特殊恐惧的文字。这个名称描述恐惧对象，不能凭一次担心设备安全，就认定某人患有一种疾病。','mechanophobia in literature；fear described as mechanophobia。','technophobia 针对技术的恐惧更广；mechanophobia 聚焦机器。谨慎操作与强烈恐惧也不是同一件事。',('The article describes the character’s fear of machines as mechanophobia.','文章把角色对机器的恐惧称为 mechanophobia。'),('The seminar contrasts mechanophobia with enthusiasm for automation.','研讨会对比了对机器的恐惧与对自动化的热情。'),sources=['https://en.wiktionary.org/wiki/mechanophobia#English']),
]
SPIR_ROOT=dict(id='C1395',meaning='呼吸、吹气；生命气息到精神与追求',core='先想到一口气：能维持生命，也能比喻心里的劲头。前缀给这口气不同方向，词义便走向激励、追求、终止、共谋等支线。',image='spirit 是生命与心里的气；inspire 像吹入活力；expire 是呼出、终止。呼吸这一画面帮助理解，但具体转义要按历史分别看。',intro='拉丁 spirare 表吹气、呼吸，更早来源未定。spiritus 的呼吸、生命气息义扩展为精神、灵魂。aspirare、inspirare、exspirare 等在拉丁语中已有各自用法，英语又经法语及学术借词发展，不能把今天的英文词简单拼出来当历史。',forms='spir-、spirat- 接呼吸词干；in- 吹入、ex- 呼出、re- 再次、per- 穿透、trans- 穿过。拉丁 ad- 与 spirare 形成 aspirare，con- 与它形成 conspirare。spiritual 与 spirited 的英语词尾带出不同含义。',branches=[['生命、精神与劲头','spirit, spiritual, spirituality, spiritually, spirited, dispirited'],['激励、灵感与吸气','inspire, inspiration, inspired, inspiring, inspirational'],['志向与专业气流用法','aspire, aspiration, aspirant, aspirational, aspirate'],['呼出、期限与呼吸','expire, expiration, expiry, expired, expiratory, respiration, respiratory, respirator'],['共谋、出汗与蒸腾','conspire, conspiracy, conspirator, conspiratorial, perspire, perspiration, transpire, transpiration']],contrasts='spiritual 是精神或灵性方面，spirited 是有劲头。inspiration 在医疗中是吸气，在创作中是灵感。aspirate 的医学抽吸、误吸要按语境分方向。respirator 与 ventilator 的现代用途也不能只凭中文“呼吸器”混为一谈。',practice='分别用一句话说明 inspire confidence、career aspirations、an expiry date、cellular respiration。再说清 perspiration 比 perspire 早这件事，怎样提醒我们不要只按词尾推历史。',words=list(ASSIGN['roots'][45]['family']),exclude={})
COR_ROOT=dict(id='C0259',meaning='身体；把成员、材料组织成一个整体',core='把许多部分看成一个身体：既能是人的肉身，也能是共同工作的团体、可分析的材料集合。',image='corpus 是一个整体；corps 是人员整体；corporation 是组织整体；incorporate 是把部分纳进整体。corporeal 则问有没有物质身体。',intro='拉丁 corpus 的属格 corporis 给出 corpor- 词干。英语词经过不同借入路线：corps 保留法语读音，corpse 主要指遗体，corpus 作为学术借词保留拉丁复数 corpora。corporal 的身体形容词属于此族，军衔义另从 caput“头、首领”一支进入，不强行说成同一个身体故事。',forms='corpor- 常接组织与身体的派生词；corpore- 接 corporeal 等有形体词。corpusculum 是 corpus 的指小形式，带来 corpuscle。in- 在 incorporate 中表进入，在 incorporeal 中是否定，方向必须由各词历史确认。',branches=[['身体、群体与材料整体','corpse, corps, corpus, corpora, corporal'],['公司与结合','corporate, corporation, incorporate, incorporation, incorporated, unincorporated, corporately'],['重新结合、解除与古旧合一','reincorporate, reincorporation, disincorporate, disincorporation, concorporate, concorporation'],['有形与无形的身体','corporeal, corporeally, corporeality, corporeity, incorporeal, incorporeality, incorporeity, corporality, corporature, extracorporeal'],['小体、体态和体数','corpuscle, corpuscular, corpulent, corpulence, bicorporal, tricorporal'],['行业团体的组织思想','corporative, corporatism, corporatist']],contrasts='corps 的 ps 在单数不读，corpse 则读 /ps/。corporately 是作为团体，corporeally 是以肉身。incorporeal 无形体，extracorporeal 在体外，corpulent 说肥胖，三个词不是同一种身体描述。',practice='把 a corpus of letters、a diplomatic corps、a corporation 分别还原成什么样的整体。再解释 incorporate feedback 与 incorporeal rights 中两个 in- 为什么方向不同。',words=list(ASSIGN['roots'][46]['family']),exclude={})
MECH_ROOT=dict(id='C0712',meaning='工具、巧妙装置；机制与谋划',core='一个设计好的装置，让各部分按顺序起作用；同一个早期词也能指达成目的的巧计。',image='machine 是装置，mechanism 是里面怎样运转，mechanics 研究力与运动；machination 把巧妙安排用于暗中算计。',intro='希腊 mekhane 及多里斯方言 makhana 表工具、装置、办法；更远源头有争论，不强接到另一个确定的印欧词根。machine 经拉丁 machina、法语借入，mechanic 和 mechanism 各走相关学术支线。machination 保留计策方向，历史上早于英语 machinate。',forms='machin- 多见于 machine、machinery、machinist；mechan- 多见于机械性质、机制、力学名称；mechano- 是现代组合成分。机电一体化 mechatronics 是现代融合词，并非古词原样延续。',branches=[['机器、加工与修理','machine, machinery, mechanic, machinist, mechanical, mechanically, submachine'],['机构与解释机制','mechanism, mechanistic, mechanistically, mechanics'],['采用机械','mechanize, mechanized, mechanization'],['生命与电子系统','biomechanics, mechanobiology, mechatronics'],['巧计与幕后谋划','machination, machinate, machinator'],['对机器的态度','mechanophilia, mechanophobia']],contrasts='mechanic 常检修，machinist 常加工；mechanism 是运行机构或过程，mechanics 是力学或操作细节。mechanize 引入机器，automate 强调自动执行。mechanistic explanation 可是严谨的机制解释，不必是贬义“呆板”。',practice='用 machine、machinery、mechanism 描写同一个工厂，但让三句话关注不同层面。再说明 machination 为什么与机器同源，却不是一种机器名称。',words=list(ASSIGN['roots'][47]['family']),exclude={})
